  font-size: 12px;
  color: var(--palette-text-subtle);
  margin: 0;
}

.actiondeck-placeholder .placeholder-hint {
  font-size: 11px;
  color: var(--palette-text-muted);
  margin-top: 16px;
}

.actiondeck-settings-header {
  height: auto;
  min-height: 52px;
  padding-top: 8px;
  padding-bottom: 8px;
}

.actiondeck-settings-heading {
  display: flex;
  flex-direction: column;
  min-width: 0;
  gap: 2px;
}

.actiondeck-settings-kicker {
  font-size: 11px;
  color: rgba(255, 244, 214, 0.72);
  letter-spacing: 0.04em;
}

.actiondeck-settings-body {
  display: grid;
  gap: 14px;
  padding: 16px;
  background: radial-gradient(circle at top right, rgba(255, 224, 141, 0.14), transparent 34%), linear-gradient(180deg, rgba(41, 46, 96, 0.98), rgba(42, 46, 97, 0.96));
  flex: 1;
  min-height: 0;
  overflow: auto;
}

.actiondeck-setting {
  display: grid;
  gap: 6px;
  padding: 12px 14px;
  border: 1px solid rgba(53, 209, 197, 0.18);
  border-radius: 10px;
  background: rgba(40, 45, 95, 0.62);
}

.actiondeck-setting-label {
  font-size: 12px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #fff4d7;
}

.actiondeck-setting-value {
  font-size: 15px;
  color: #fff4d8;
}

.actiondeck-setting input[type="range"] {
  width: 100%;
  accent-color: #fbdf91;
}

.actiondeck-setting-inline {
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 12px;
}

.actiondeck-settings-input, .actiondeck-settings-select {
  width: 100%;
  min-width: 0;
  border: 1px solid rgba(53, 209, 197, 0.22);
  border-radius: 8px;
  background: rgba(39, 44, 91, 0.9);
  color: #fef8e6;
  padding: 10px 12px;
  font-size: 13px;
}

.actiondeck-settings-input::placeholder {
  color: rgba(225, 215, 181, 0.5);
}

.actiondeck-settings-input:focus, .actiondeck-settings-select:focus {
  outline: none;
  border-color: rgba(251, 223, 145, 0.5);
  box-shadow: 0 0 0 3px rgba(251, 223, 145, 0.08);
}

.actiondeck-btn.mode.is-on {
  border-color: rgba(251, 223, 145, 0.5);
  color: #fff4d8;
}

.add-from-backdrop {
  position: fixed;
  inset: 0;
  z-index: 25;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgba(35, 39, 87, 0.64);
  backdrop-filter: blur(10px);
}

.add-from-picker {
  width: min(560px, 94vw);
  max-height: min(680px, 86vh);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid rgba(83, 211, 200, 0.3);
  border-radius: 13px;
  background: rgba(41, 46, 96, 0.98);
  box-shadow: 0 28px 80px rgba(23, 25, 65, 0.62);
  color: rgba(251, 246, 233, 0.88);
}

.add-from-head, .add-from-footer, .add-from-when {
  display: flex;
  align-items: center;
}

.add-from-head {
  justify-content: space-between;
  padding: 16px 18px 12px;
}

.add-from-head span, .add-from-head strong {
  display: block;
}

.add-from-head span {
  color: #5bd2c7;
  font-size: 13px;
  font-weight: 650;
}

.add-from-head strong {
  margin-top: 2px;
  color: rgba(250, 244, 230, 0.42);
  font-size: 9px;
  letter-spacing: 0.08em;
}

.add-from-head button {
  border: 0;
  background: transparent;
  color: rgba(251, 246, 234, 0.54);
  font-size: 22px;
  cursor: pointer;
}

.add-from-search {
  margin: 0 18px 10px;
  padding: 10px 11px;
  border: 1px solid rgba(83, 207, 196, 0.18);
  border-radius: 7px;
  outline: 0;
  background: rgba(254, 251, 241, 0.045);
  color: rgba(252, 248, 235, 0.9);
  font: inherit;
}

.add-from-search:focus {
  border-color: rgba(82, 212, 201, 0.48);
}

.add-from-sources {
  min-height: 190px;
  overflow-y: auto;
  padding: 0 12px 10px;
}

.add-from-sources>button {
  width: 100%;
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr) 18px;
  align-items: center;
  gap: 9px;
  margin: 3px 0;
  padding: 9px 10px;
  border: 1px solid transparent;
  border-radius: 7px;
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
}

.add-from-sources>button:hover {
  background: rgba(254, 251, 241, 0.035);
}

.add-from-sources>button.selected {
  border-color: rgba(83, 211, 200, 0.25);
  background: rgba(78, 205, 194, 0.08);
}

.add-from-sources i {
  width: 22px;
  height: 22px;
  display: grid;
  place-items: center;
  border-radius: 6px;
  background: rgba(181, 206, 53, 0.14);
  color: #e3d195;
  font-size: 9px;
  font-style: normal;
  font-weight: 700;
}

.add-from-sources i.forest {
  background: rgba(114, 169, 170, 0.14);
  color: #58cdc3;
}

.add-from-sources span {
  min-width: 0;
}

.add-from-sources strong, .add-from-sources small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.add-from-sources strong {
  font-size: 11px;
  font-weight: 570;
}

.add-from-sources small {
  margin-top: 3px;
  color: rgba(249, 243, 229, 0.4);
  font-size: 9px;
}

.add-from-sources b {
  color: #5ad1c6;
  font-size: 11px;
}

.add-from-empty {
  padding: 38px 12px;
  color: rgba(248, 243, 229, 0.42);
  font-size: 11px;
  text-align: center;
}

.add-from-when {
  gap: 10px;
  padding: 12px 18px;
  border-top: 1px solid rgba(85, 210, 199, 0.1);
  border-bottom: 1px solid rgba(85, 210, 199, 0.1);
  background: rgba(254, 251, 241, 0.018);
}

.add-from-when label {
  flex: 1;
}

.add-from-when span {
  display: block;
  margin-bottom: 4px;
  color: rgba(248, 243, 228, 0.45);
  font-size: 8px;
  text-transform: uppercase;
}

.add-from-when input, .add-from-when select {
  width: 100%;
  box-sizing: border-box;
  padding: 6px;
  border: 1px solid rgba(84, 207, 196, 0.16);
  border-radius: 5px;
  background: rgba(254, 251, 241, 0.035);
  color: rgba(251, 246, 233, 0.8);
  font: inherit;
  font-size: 10px;
}

.add-from-error {
  padding: 8px 18px 0;
  color: #7cc0ca;
  font-size: 10px;
}

.add-from-footer {
  justify-content: space-between;
  gap: 12px;
  padding: 13px 18px 16px;
}

.add-from-footer span {
  min-width: 0;
  overflow: hidden;
  color: rgba(239, 235, 220, 0.46);
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.add-from-footer button {
  flex: 0 0 auto;
  padding: 7px 11px;
  border: 1px solid rgba(223, 205, 146, 0.38);
  border-radius: 6px;
  background: rgba(75, 202, 191, 0.11);
  color: #decf9d;
  font-size: 10px;
  cursor: pointer;
}

.add-from-footer button:disabled {
  opacity: 0.35;
  cursor: default;
}

