:root[data-theme='medieval-taurus'], :root[data-theme='caspian-sea'] {
  --cc-font-size-tiny: 10.05px;
  --cc-font-size-small: 17.42px;
  --cc-font-size-medium: 21.44px;
  --cc-font-size-large: 29.48px;
  --cc-font-size-huge: 53.6px;
}

body {
  background: var(--ui-body-bg, #171941);
  color: var(--ui-text-primary);
  border-radius: var(--cc-radius-none);
  margin: 0px !important;
}

.app {
  display: flex;
  flex-direction: column;
  position: relative;
  height: 100vh;
  background: linear-gradient(var(--ui-body-bg), var(--ui-app-bg));
  background-repeat: var(--ui-bg-repeat, no-repeat);
  color: var(--ui-text-primary);
  font-family: var(--ui-font-main, Chillax);
  overflow: hidden;
  border: var(--ui-app-border);
  border-radius: var(--ui-app-border-radius);
  box-shadow: var(--ui-app-shadow);
}

.app.theme-studio-docked {
  width: calc(100% - var(--theme-studio-width, 320px));
}

@media (max-width: 920px) {
  .app.theme-studio-docked {
    width: 100%;
  }

}
.app-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  gap: var(--cc-gap-huge);
  position: relative;
  height: var(--cc-app-header-height);
  top: 0;
  z-index: 34;
  color: var(--ui-header-text, #f9f6ec);
  padding: 0;
  background: var(--ui-header-bg);
  flex-shrink: 0;
  border-radius: var(--cc-radius-none) !important;
  user-select: none;
  overflow: hidden;
  transition: all .15s cubic-bezier(.3, .8, .7, 1.1);
  transition-delay: 0s;
}

.app-header:hover {
  height: var(--cc-app-header-height);
  transform: scale(1);
  transition-delay: 0s;
}

.app-header.shrinkable {
  overflow: hidden;
  transition: all .2s cubic-bezier(.5, .9, .5, 1);
  transition-delay: 5s;
}

.app-header.shrunk {
  transition-delay: 5s;
}

.app-header.shrinkable:hover, .app-header.shrunk:hover {
  height: var(--cc-app-header-height);
  transition-delay: 0s;
}

.app-header.shrunk:not(:hover) .title-text, .app-header.shrunk:not(:hover) .header-dock-slot, .app-header.shrunk:not(:hover) .header-right {
  opacity: 0;
  transition: all 1s;
  transition-delay: 4s;
  pointer-events: none;
  user-select: none;
}

.app-header.shrunk:hover .title-text, .app-header.shrunk:hover .header-dock-slot, .app-header.shrunk:hover .header-right {
  opacity: 1;
  transition-delay: 0s;
  pointer-events: all;
  user-select: all;
}

.header-shrink-toggle {
  opacity: .1;
  -webkit-app-region: no-drag;
  appearance: none;
  position: absolute;
  bottom: 4px;
  right: 4px;
  z-index: 4000;
  display: grid;
  width: 30px;
  height: 40px;
  padding: 0;
  place-items: center;
  border: 1px solid color-mix(in oklab, var(--palette-accent-primary, #42d3c7) 74%, transparent);
  border-radius: var(--cc-radius-slight);
  background: color-mix(in oklab, var(--ui-header-bg, #242954) 88%, transparent);
  color: var(--palette-accent-primary, #42d3c7);
  box-shadow: 0 0 0 1px color-mix(in oklab, var(--palette-accent-primary, #42d3c7) 20%, transparent), 0 0 10px color-mix(in oklab, var(--palette-accent-primary, #42d3c7) 24%, transparent);
  cursor: pointer;
  font-family: 'SF Pro Display', 'SF Pro Symbols', 'Apple Symbols', sans-serif !important;
  font-size: 19px;
  line-height: 1;
  text-shadow: 0 0 7px currentColor;
  transition: color .15s ease, background .15s ease, border-color .15s ease, box-shadow .15s ease;
}

.header-shrink-toggle:hover, .header-shrink-toggle:focus-visible, .header-shrink-toggle.is-active {
  border-color: var(--palette-accent-primary, #42d3c7);
  background: color-mix(in oklab, var(--ui-header-bg, #242954) 72%, var(--palette-accent-primary, #42d3c7));
  color: color-mix(in oklab, var(--palette-accent-primary, #42d3c7) 74%, #fefbf1);
  box-shadow: 0 0 0 1px color-mix(in oklab, var(--palette-accent-primary, #42d3c7) 34%, transparent), 0 0 14px color-mix(in oklab, var(--palette-accent-primary, #42d3c7) 48%, transparent);
  outline: none;
  opacity: 1;
}

.header-shrink-toggle.is-active {
  right: 50%;
  transform: translateX(50%)scaleY(.5);
}

.header-shrink-toggle:focus-visible {
  outline: 1px solid currentColor;
  outline-offset: 2px;
}

.app:not(.app--vertical-header) .header-right {
  padding-right: 32px;
}

.app--vertical-header .header-shrink-toggle {
  display: none;
}

.header-title {
  width: 30vw;
  height: 100%;
  color: var(--ui-header-titlecolor, #fefbf1);
  display: flex;
  align-items: center;
  gap: var(--cc-gap-large);
  padding: var(--cc-padding-tiny) !important;
  pointer-events: all !important;
  justify-self: start;
  min-width: 0;
  border-radius: var(--cc-radius-none) !important;
}

.header-dock-slot {
  justify-self: center;
  width: 75vw;
  min-width: 260px;
  max-width: 100%;
}

.header-right {
  display: flex;
  align-items: center;
  justify-self: end;
  gap: var(--cc-gap-large);
  min-width: 0;
}

.title-icon {
  display: contents;
  color: var(--ui-title-icon);
  font-size: var(--cc-font-size-large);
  text-shadow: var(--ui-title-icon-glow);
  transition: all 1.4s cubic-bezier(0.5, .2, 0.7, 1.1), filter 5s ease;
}

.title-icon::before {
  content: "᳀";
  filter: brightness(1)blur(0px);
  transition: all 1.4s cubic-bezier(0.5, .2, 0.7, 1.1), filter 2.5s ease;
}

.title-icon:hover .title-icon::before, .app-header:hover .title-icon::before {
  transform: scale(2.5)rotate(720deg);
}

.title-icon:active .title-icon::before, .header-title:active .title-icon::before {
  transform: scale(4)rotate(720deg);
  filter: brightness(3)blur(1px);
  transition: transform .3s ease, filter 1s ease;
}

.title-text {
  -webkit-app-region: drag;
  text-transform: var(--ui-title-transform, none);
  font-size: var(--ui-title-size, var(--cc-font-size-large));
  font-weight: var(--ui-title-weight, 400);
  background: var(--ui-title-gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  -webkit-text-stroke: var(--ui-title-stroke);
  transition: all .2s ease;
  background-size: 400% 400%;
  animation: backflow 10s linear infinite;
  animation-duration: var(--ui-title-duration, 10s);
  letter-spacing: 1.5px;
}

.header-datetime-weather {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  margin: 0;
  font-size: var(--cc-font-size-small);
  letter-spacing: 1px;
  opacity: 0.7;
  -webkit-app-region: drag !important;
}

.header-time {
  color: var(--palette-accent-primary);
  font-weight: 600;
}

.header-date {
  font-weight: 400;
  color: var(--palette-accent-primary);
}

.header-weather {
  font-weight: 600;
}

.app--vertical-header {
  --vertical-header-width: 96px;
  position: relative;
}

.app--vertical-header .app-header {
  position: absolute;
  inset: 0 auto 0 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr) auto;
  width: var(--vertical-header-width);
  height: 100%;
  box-sizing: border-box;
  gap: var(--cc-gap-none);
  padding: var(--cc-padding-large) var(--cc-padding-medium) var(--cc-padding-huge);
  margin: 0;
  overflow: visible;
  border-right: 1px solid color-mix(in oklab, var(--palette-accent-primary, #6b6de0) 52%, transparent);
  background: var(--ui-header-bg);
  box-shadow: inset -1px 0 rgba(248, 243, 231, 0.12), inset -13px 0 22px color-mix(in oklab, var(--palette-accent-primary, #6667d7) 22%, transparent), 7px 0 18px rgba(23, 25, 65, 0.3);
}

.app--vertical-header .header-title {
  grid-row: 1;
  width: 100%;
  height: 76px;
  min-width: 0;
  align-items: flex-start;
  justify-content: center;
  justify-self: stretch;
}

.app--vertical-header .title-icon {
  display: grid;
  width: 68px;
  height: 68px;
  place-items: center;
  color: var(--ui-title-icon);
  font-size: var(--cc-font-size-large);
  line-height: 1;
}

.app--vertical-header .title-icon::before {
  font-size: var(--cc-font-size-large);
  line-height: 1;
}

.app--vertical-header .app-header:hover .title-icon::before {
  transform: none;
}

.app--vertical-header .title-text, .app--vertical-header .title-icon\:before {
  display: none;
}

.app--vertical-header .header-dock-slot {
  grid-row: 2;
  display: flex;
  width: 100%;
