#controlBar {
  transition: height .5s, min-height .5s, opacity .25s, filter .55s;
  display: flex;
  align-items: center;
  background: var(--ui-controlbar-bg);
  box-shadow: var(--ui-controlbar-shadow);
  gap: var(--cc-gap-huge);
  z-index: 16;
  background-size: var(--ui-controlbar-bg-size, 400% 400%);
  background-position: var(--ui-controlbar-bg-position, 0% 0%);
  justify-content: center;
  height: 100px;
  overflow: hidden;
  animation: backflow var(--ui-controlbar-bg-speed, 200s) linear infinite;
  filter: var(--ui-controlbar-filter);
  pointer-events: auto;
}

#controlBar:hover {
  transition: height .5s, opacity 2s, filter .55s;
  filter: var(--ui-controlbar-filter-hover);
}

#controlBar.closed {
  transition: height .5s, min-height .5s, opacity .25s, filter .55s;
