  font-size: var(--cc-font-size-medium) !important;
  font-family: inherit;
  min-height: 20px;
  height: 100%;
  resize: none;
  padding: var(--cc-padding-large) var(--cc-padding-small);
  overflow: hidden;
  letter-spacing: -1px;
  transition: all 0.3s ease !important;
}

* {
  box-sizing: border-box;
}

.chat-textarea::-webkit-scrollbar {
  width: 1px;
}

.chat-textarea:focus {
  min-height: 60px;
