  font-weight: 700;
  line-height: 1;
  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease, transform 0.15s ease;
}

.confirmation-response-btn.approve, .confirmation-btn.confirm {
  color: var(--palette-success, #b2cc12);
