  border: 1px solid color-mix(in srgb, var(--palette-success, #b2cc12) 60%, transparent);
}

.confirmation-response-btn.decline, .confirmation-btn.cancel {
  color: var(--palette-danger, #ec6b68);
  background: color-mix(in srgb, var(--palette-danger, #ec6b68) 12%, transparent);
  border: 1px solid color-mix(in srgb, var(--palette-danger, #ec6b68) 52%, transparent);
}

@media (hover: hover) {
  .confirmation-response-btn.approve:hover, .confirmation-btn.confirm:hover {
    background: color-mix(in srgb, var(--palette-success, #b2cc12) 28%, transparent);
    border-color: var(--palette-success, #b2cc12);
  }

  .confirmation-response-btn.decline:hover, .confirmation-btn.cancel:hover {
    background: color-mix(in srgb, var(--palette-danger, #ec6b68) 24%, transparent);
    border-color: var(--palette-danger, #ec6b68);
  }

}
.confirmation-response-btn:active, .confirmation-btn:active {
  transform: translateY(1px);
}

.confirmation-response-btn:focus-visible, .confirmation-btn:focus-visible, .chat-confirmation-request:focus-visible, .confirmation-toast:focus-visible {
