  z-index: 16;
}

.message-tooltip-user {
  position: absolute;
  right: 50%;
  bottom: 90%;
  transform: translateX(10%)translateY(60%);
  border: 1px solid rgba(48, 215, 203, 0.3);
  border-radius: var(--cc-radius-slight);
  padding: var(--cc-padding-small);
  display: flex;
  gap: var(--cc-gap-medium);
