/* Focus-mode prep + steps: the viewed activity's bullets, anchored at
   the left and joined to that activity's card by an elbow connector
   in the card's hue. --bzf-card-x is the measured drop point just
   inside the viewed card's left edge; only the connector moves when
   the selection changes, never the text. */
.bzf-focus-detail {
  --bzf-path: var(--bzf-warn);
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-height: 200px;
  padding: 28px 8px 4px 20px;
}

/* The elbow: across from under the viewed card, then down to the
   first dot (border-top + border-left of one box). */
.bzf-focus-detail::before {
  content: '';
  position: absolute;
  top: 6px;
  left: 24.5px;
  width: calc(var(--bzf-card-x, 26px) - 24.5px);
  height: 23px;
  border-top: 2px solid color-mix(in srgb, var(--bzf-path) 62%, transparent);
  border-left: 2px solid color-mix(in srgb, var(--bzf-path) 62%, transparent);
  transition: width 260ms cubic-bezier(0.22, 1, 0.36, 1);
}

/* The drop from the viewed card down to the elbow. */
.bzf-focus-detail::after {
  content: '';
  position: absolute;
  top: -20px;
  height: 28px;
  width: 2px;
  left: calc(var(--bzf-card-x, 26px) - 2px);
  background: color-mix(in srgb, var(--bzf-path) 62%, transparent);
  transition: left 260ms cubic-bezier(0.22, 1, 0.36, 1);
}

.bzf-focus-section {
  position: relative;
  padding-left: 24px;
}

.bzf-focus-section::before {
  content: '';
  position: absolute;
  left: 0;
  top: 1px;
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: var(--bzf-path);
  box-shadow: 0 0 9px color-mix(in srgb, var(--bzf-path) 55%, transparent);
}

.bzf-focus-section:not(:last-child)::after {
  content: '';
  position: absolute;
  left: 4.5px;
  top: 13px;
  bottom: -18px;
  width: 2px;
  background: color-mix(in srgb, var(--bzf-path) 62%, transparent);
}

.bzf-focus-label {
  margin-bottom: 3px;
  color: #fefbf1;
  font-size: 12.5px;
  font-weight: 700;
}

.bzf-focus-detail .bzf-detail-list {
  color: var(--bzf-text);
}

.bzf-focus-detail .bzf-muted {
  color: var(--bzf-text-muted);
  font-size: 12px;
}

.bzf-focus-detail.bzf-hue-0 {
  --bzf-path: color-mix(in srgb, var(--bzf-accent) 72%, #fae4a9);
}

.bzf-focus-detail.bzf-hue-1 {
  --bzf-path: color-mix(in srgb, var(--bzf-violet) 52%, #4aa9ea);
}

.bzf-focus-detail.bzf-hue-2 {
  --bzf-path: color-mix(in srgb, var(--bzf-violet) 74%, #7bc3cd);
}

.bzf-focus-detail.is-current {
  --bzf-path: var(--bzf-warn);
}

