  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.dock-style-options {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  min-width: 0;
  padding: 0;
  margin: 2px 0 0;
  border: 0;
}

.dock-style-option {
  position: relative;
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 10px;
  padding: 10px;
  overflow: hidden;
  border: 1px solid var(--ui-settings-radio-border, rgba(83, 205, 194, 0.2));
  border-radius: 10px;
  background: var(--ui-settings-radio-bg, rgba(47, 52, 105, 0.72));
  cursor: pointer;
  transition: border-color 140ms ease-out, background 140ms ease-out, box-shadow 180ms ease-out, transform 140ms ease-out;
  corner-shape: var(--ui-corner-shape);
}

.dock-style-option:hover {
  border-color: var(--ui-settings-radio-border-hover, rgba(72, 213, 202, 0.5));
  background: var(--ui-settings-radio-bg-hover, rgba(54, 60, 117, 0.82));
  transform: translateY(-1px);
}

.dock-style-option:has(input:checked) {
  border-color: var(--ui-settings-radio-border-active, rgba(228, 207, 140, 0.8));
  background: var(--ui-settings-radio-bg-active, rgba(66, 73, 136, 0.72));
  box-shadow: var(--ui-settings-radio-shadow-active, 0 0 0 1px rgba(228, 207, 140, 0.22));
}

.dock-style-option:has(input:focus-visible) {
  outline: 2px solid var(--palette-accent-cyan, #3cd7cb);
  outline-offset: 3px;
}

.dock-style-option input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}

.dock-style-option-check {
  position: absolute;
  top: 7px;
  right: 8px;
  display: grid;
  width: 18px;
  height: 18px;
  place-items: center;
  border: 1px solid rgba(254, 251, 241, 0.16);
  border-radius: 50%;
  background: rgba(39, 44, 91, 0.72);
  color: rgba(250, 245, 232, 0.42);
  font-size: 10px;
  opacity: 0;
  transform: scale(0.7);
  transition: opacity 120ms ease-out, transform 180ms cubic-bezier(0.22, 1, 0.36, 1);
}

.dock-style-option:has(input:checked) .dock-style-option-check {
  color: var(--palette-accent-cyan, #3cd7cb);
  opacity: 1;
  transform: scale(1);
}

.dock-style-preview {
  position: relative;
  display: grid;
  height: 76px;
  min-width: 0;
  place-items: center;
  overflow: hidden;
  border-radius: 7px;
  background: radial-gradient(circle at 50% 115%, rgba(39, 167, 158, 0.15), transparent 54%), linear-gradient(155deg, rgba(41, 46, 93, 0.94), rgba(36, 41, 87, 0.98));
  box-shadow: inset 0 0 0 1px rgba(234, 226, 199, 0.08);
}

.dock-style-preview::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(112deg, transparent 22%, rgba(254, 251, 241, 0.045) 50%, transparent 76%);
  pointer-events: none;
}

.dock-style-preview-track {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

.dock-style-preview-item {
  --dock-preview-accent: #3cd7cb;
  position: relative;
  display: grid;
  place-items: center;
  color: var(--dock-preview-accent);
}

.dock-style-preview-glyph {
  position: relative;
  z-index: 2;
  font-family: 'SF Pro', -apple-system, BlinkMacSystemFont, sans-serif;
  line-height: 1;
}

.dock-style-preview--current .dock-style-preview-track {
  gap: clamp(12px, 1.8vw, 23px);
}

.dock-style-preview--current .dock-style-preview-item {
  width: 24px;
  height: 36px;
  opacity: 0.42;
  filter: blur(2px) saturate(0.75);
}

.dock-style-preview--current .dock-style-preview-item.is-active {
  opacity: 1;
  filter: none;
}

.dock-style-preview--current .dock-style-preview-item.is-active::after {
  content: '';
  position: absolute;
  right: -6px;
  bottom: 1px;
  left: -6px;
  height: 3px;
  border-radius: 999px;
  background: linear-gradient(90deg, transparent, rgba(252, 247, 235, 0.88), transparent);
  box-shadow: 0 0 6px var(--dock-preview-accent);
}

.dock-style-preview--current .dock-style-preview-glyph {
  font-size: 21px;
}

.dock-style-preview--macos .dock-style-preview-track {
  gap: 4px;
  padding: 5px 7px 6px;
  border: 1px solid rgba(239, 235, 222, 0.32);
  border-radius: 12px;
  background: linear-gradient(180deg, rgba(238, 234, 222, 0.38), rgba(89, 107, 113, 0.56));
  box-shadow: inset 0 1px rgba(254, 251, 241, 0.32), 0 7px 15px rgba(23, 25, 65, 0.3);
}

.dock-style-preview--macos .dock-style-preview-item {
  width: 31px;
  height: 31px;
  border: 1px solid color-mix(in oklab, var(--dock-preview-accent) 62%, #fefbf1);
  border-radius: 8px;
  background: linear-gradient(155deg, rgba(254, 251, 241, 0.36), transparent 44%), color-mix(in oklab, var(--dock-preview-accent) 66%, #3a4176);
  box-shadow: inset 0 -1px rgba(23, 25, 65, 0.24), 0 2px 4px rgba(23, 25, 65, 0.3);
}

.dock-style-preview--macos .dock-style-preview-item.is-active {
  transform: translateY(-5px) scale(1.14);
}

.dock-style-preview--macos .dock-style-preview-item.is-active::after {
  content: '';
  position: absolute;
  bottom: -7px;
  left: 50%;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: rgba(251, 247, 236, 0.88);
  transform: translateX(-50%);
}

.dock-style-preview--macos .dock-style-preview-glyph {
  color: rgba(252, 248, 237, 0.95);
  font-size: 17px;
  filter: drop-shadow(0 1px rgba(23, 25, 65, 0.4));
}

.dock-style-preview--tabs {
  align-items: end;
  padding-bottom: 12px;
}

.dock-style-preview--tabs::after {
  content: '';
  position: absolute;
  right: 10px;
  bottom: 12px;
  left: 10px;
  height: 1px;
  background: rgba(59, 212, 200, 0.68);
  box-shadow: 0 0 7px rgba(59, 212, 200, 0.38);
}

.dock-style-preview--tabs .dock-style-preview-item {
  z-index: 1;
  width: 50px;
  height: 32px;
  margin: 0 -3px;
  opacity: 0.62;
}

.dock-style-preview--tabs .dock-style-preview-item.is-active {
  z-index: 3;
  width: 65px;
  opacity: 1;
  transform: translateY(-2px);
}

.dock-style-preview-tab {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.dock-style-preview-tab path {
  fill: rgba(119, 135, 135, 0.8);
  stroke: rgba(234, 230, 217, 0.64);
  stroke-width: 0.8;
  vector-effect: non-scaling-stroke;
}

.dock-style-preview--tabs .is-active .dock-style-preview-tab path {
  fill: rgba(38, 42, 88, 0.98);
  stroke: rgba(58, 214, 202, 0.92);
  stroke-width: 1.2;
}

.dock-style-preview--tabs .dock-style-preview-glyph {
  font-size: 18px;
  filter: saturate(0.72);
}

.dock-style-preview--tabs .is-active .dock-style-preview-glyph {
  filter: saturate(1.25) drop-shadow(0 0 3px var(--dock-preview-accent));
}

.dock-style-option-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
}

.dock-style-option-label {
  color: var(--ui-settings-radio-label, rgba(248, 243, 229, 0.92));
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.dock-style-option:has(input:checked) .dock-style-option-label {
  color: var(--ui-settings-radio-label-active, var(--palette-accent-cyan, #3cd7cb));
}

.dock-style-option-description {
  color: var(--ui-settings-section-desc, rgba(212, 204, 180, 0.68));
  font-size: 10px;
  line-height: 1.4;
}

.dock-orientation-setting {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 3px;
  width: 32%;
  padding-top: 4px;
}

.dock-orientation-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
}

.dock-orientation-label {
  color: var(--ui-settings-radio-label, rgba(248, 243, 229, 0.92));
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.dock-orientation-hint {
  color: var(--ui-settings-section-desc, rgba(212, 204, 180, 0.68));
  font-size: 10px;
}

.dock-orientation-options {
  display: grid;
  grid-template-columns: repeat(2, minmax(112px, 1fr));
  flex: 0 0 auto;
  gap: 3px;
  min-width: 0;
  margin: 0;
  border: 1px solid var(--ui-settings-radio-border, rgba(83, 205, 194, 0.2));
  border-radius: 9px;
  background: color-mix(in oklab, var(--ui-settings-radio-bg, rgba(47, 52, 105, 0.72)) 78%, transparent);
}

.dock-orientation-option {
  position: relative;
  display: flex;
  min-height: 38px;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 4px;
  border: 1px solid transparent;
  border-radius: 6px;
  color: var(--ui-settings-section-desc, rgba(212, 204, 180, 0.68));
  font-size: 10px;
  letter-spacing: 0.035em;
  cursor: pointer;
  transition: color 120ms ease-out, border-color 120ms ease-out, background 120ms ease-out;
}

.dock-orientation-option:hover {
  color: var(--ui-settings-radio-label, rgba(248, 243, 229, 0.92));
  background: var(--ui-settings-radio-bg-hover, rgba(54, 60, 117, 0.82));
}

.dock-orientation-option:has(input:checked) {
  border-color: var(--ui-settings-radio-border-active, rgba(228, 207, 140, 0.8));
  color: var(--ui-settings-radio-label-active, var(--palette-accent-cyan, #3cd7cb));
  background: var(--ui-settings-radio-bg-active, rgba(66, 73, 136, 0.72));
  box-shadow: inset 0 0 0 1px color-mix(in oklab, currentColor 18%, transparent);
}

.dock-orientation-option:has(input:focus-visible) {
  outline: 2px solid var(--palette-accent-cyan, #3cd7cb);
  outline-offset: 3px;
}

.dock-orientation-option.is-disabled {
  opacity: 0.34;
  cursor: not-allowed;
}

.dock-orientation-option input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}

.dock-orientation-mark {
  position: relative;
  width: 23px;
  height: 15px;
  flex: 0 0 auto;
  border: 1px solid currentColor;
  border-radius: 3px;
  opacity: 0.78;
}

.dock-orientation-mark::before {
  content: '';
  position: absolute;
  border-radius: 2px;
  background: currentColor;
  box-shadow: 0 0 5px color-mix(in oklab, currentColor 44%, transparent);
}

.dock-orientation-mark--horizontal::before {
  top: 2px;
  right: 2px;
  left: 2px;
  height: 3px;
}

.dock-orientation-mark--vertical::before {
  top: 2px;
  bottom: 2px;
  left: 2px;
  width: 3px;
}

.appearance-section-rule {
  height: 1px;
  margin: 2px 0;
  background: linear-gradient(90deg, transparent, var(--ui-settings-radio-border-hover, rgba(65, 207, 196, 0.34)), transparent);
}

.appearance-theme-studio-btn {
  width: 50%;
  background: none;
  corner-shape: var(--ui-corner-shape);
  border-radius: var(--ui-border-radius);
  margin: 2px 0 14px;
}

@media (max-width: 900px) {
  .dashboard-modal-container {
    max-width: 100vw;
  }

  .dashboard-modal-container .modal-tabs {
    width: 156px;
    flex-basis: 156px !important;
  }

}
@media (max-width: 620px) {
  .dock-style-option {
    display: flex;
  }

  .dock-orientation-setting {
    align-items: stretch;
    flex-direction: column;
  }

  .dock-orientation-options {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

}
@media (prefers-reduced-motion: reduce) {
  .dock-style-option, .dock-style-option-check, .dock-orientation-option {
    transition-duration: 0.01ms !important;
  }

  .dock-style-option:hover, .dock-style-preview--macos .dock-style-preview-item.is-active, .dock-style-preview--tabs .dock-style-preview-item.is-active {
    transform: none;
  }

}
.dashboard-agent-context {
