  min-height: 0;
  overflow: hidden;
  user-select: text;
  -webkit-user-select: text;
  container-type: inline-size;
  --stylofact-font: var(--ui-font-main), "Avenir Next", sans-serif;
  --stylofact-space-xs: 4px;
  --stylofact-space-sm: 8px;
  --stylofact-space-md: 16px;
  --stylofact-space-lg: 24px;
  --stylofact-space-xl: 32px;
  font-family: var(--stylofact-font);
  backdrop-filter: blur(10px);
}

.stylofact-panel *, .stylofact-panel *::before, .stylofact-panel *::after {
  box-sizing: border-box;
}

.stylofact-header {
  align-items: center;
  border-bottom: 1px solid var(--stylofact-rule);
  display: flex;
  gap: var(--stylofact-space-lg);
  justify-content: space-between;
  padding: 12px clamp(16px, 3cqw, 32px);
  background: color-mix(in srgb, var(--stylofact-paper) 94%, var(--stylofact-ink) 6%);
  flex: 0 0 auto;
  min-height: 64px;
  position: relative;
  z-index: 8;
}

.stylofact-wordmark {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.stylofact-wordmark h1 {
  font-size: 2.5rem;
  font-family: Virnature;
  padding: 0;
  margin: -20px 10px;
}

.stylofact-wordmark>span {
  color: var(--stylofact-orange-deep);
  font-size: clamp(20px, 2.3cqw, 31px);
  font-weight: 700;
  letter-spacing: -0.055em;
  line-height: .9;
}

.stylofact-wordmark small {
  color: var(--stylofact-muted);
  font-family: 'var(--ui-font-main) Next', var(--ui-font-main), sans-serif;
  font-size: 9px;
  letter-spacing: .1em;
  text-transform: uppercase;
}

.stylofact-project-controls {
  background: transparent;
  align-items: center;
  display: flex;
  flex-shrink: 0;
  gap: var(--stylofact-space-sm);
  min-width: 0;
}

.stylofact-project-title input {
  background: transparent;
  border: 0;
  border-bottom: 1px solid var(--stylofact-rule);
  border-radius: 0;
  color: var(--stylofact-ink);
  font: 600 12px/1.2 'var(--ui-font-main) Next', var(--ui-font-main), sans-serif;
  min-height: 34px;
  padding: 5px 3px;
  width: 100%;
}

.stylofact-project-controls select {
  background: var(--stylofact-input-bg);
  border: 1px solid var(--stylofact-input-border);
  border-radius: 3px;
  color: var(--stylofact-input-text);
  font: 600 .875rem/1.25 var(--stylofact-font);
  max-width: 220px;
  min-height: 34px;
  padding: 8px 30px 8px 12px;
  height: 40px;
  min-width: 150px;
}

.stylofact-stage-marker {
  border-bottom: 1px solid var(--stylofact-rule);
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  list-style: none;
  background: var(--ui-header-bg);
  margin: 0;
  padding: 0 18px 0 46px;
}

.stylofact-stage-marker li {
  align-items: baseline;
  color: var(--palette-text-subtle);
  display: flex;
  font: 600 10px/1 'var(--ui-font-main) Next', var(--ui-font-main), sans-serif;
  gap: 5px;
  letter-spacing: .04em;
  min-height: 34px;
  padding-top: 11px;
  text-transform: uppercase;
}

.stylofact-stage-marker li span {
  color: var(--palette-text-dim);
  font-family: Georgia, serif;
  font-size: 11px;
}

.stylofact-stage-marker li.complete {
  color: var(--stylofact-orange-deep);
}

.stylofact-stage-marker li.complete span {
  color: var(--stylofact-orange);
}

.stylofact-scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding-bottom: 42px;
  backdrop-filter: none;
  animation: stylofact-stage-in 220ms cubic-bezier(.22, 1, .36, 1);
  padding: 0;
}

.stylofact-section {
  border-bottom: 1px solid var(--stylofact-rule);
  padding: clamp(28px, 4.5cqw, 56px) clamp(20px, 5.5cqw, 64px) 56px;
  border: 0;
  margin: 0 auto;
  max-width: 1040px;
  min-height: 100%;
}

.stylofact-section.is-voice {
  background: var(--stylofact-paper-deep);
}

.stylofact-section.is-output {
  background: var(--stylofact-success-wash);
}

.stylofact-section-intro {
  align-items: flex-start;
  display: grid;
  gap: 13px;
  grid-template-columns: 31px minmax(0, 700px);
  margin-bottom: 19px;
}

.stylofact-step-number {
  color: var(--stylofact-orange);
  font: 700 11px/1 'var(--ui-font-main) Next', var(--ui-font-main), sans-serif;
  letter-spacing: .08em;
  padding-top: 4px;
}

.stylofact-kicker {
  color: var(--stylofact-orange-deep);
  display: block;
  font: 700 9px/1.2 'var(--ui-font-main) Next', var(--ui-font-main), sans-serif;
  letter-spacing: .14em;
  text-transform: uppercase;
}

.stylofact-section h2 {
  color: var(--stylofact-ink);
  font-size: clamp(22px, 3.2cqw, 38px);
  font-weight: 500;
  letter-spacing: -.045em;
  line-height: .98;
  margin: 5px 0 9px;
}

.stylofact-section-intro p {
  color: var(--stylofact-muted);
  font-size: 14px;
  line-height: 1.36;
  margin: 0;
  max-width: 660px;
}

.stylofact-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.stylofact-field>span {
  color: var(--stylofact-ink);
  font: 650 .8125rem/1.25 var(--stylofact-font);
  letter-spacing: 0;
  text-transform: none;
}

.stylofact-field input, .stylofact-field textarea, .stylofact-field select {
  background: var(--stylofact-input-bg);
  border: 1px solid var(--stylofact-input-border);
  border-radius: 3px;
  color: var(--stylofact-input-text);
  font: 400 1rem/1.5 var(--stylofact-font);
  min-height: 44px;
  padding: 10px 12px;
  resize: vertical;
}

.stylofact-field textarea {
  min-height: 124px;
  resize: vertical;
}

.stylofact-field small, .stylofact-approval-toggle small, .stylofact-format-list small {
  color: var(--stylofact-muted);
  font: 11px/1.25 'var(--ui-font-main) Next', var(--ui-font-main), sans-serif;
}

.stylofact-field-query {
  max-width: 760px;
  margin-bottom: 14px;
  margin: 0 0 28px;
}

.stylofact-model-grid {
  display: grid;
  gap: 16px;
  grid-template-columns: 1fr;
  margin: 0;
  padding: 4px 0 20px;
}

.stylofact-corpus {
  border-left: 2px solid var(--stylofact-orange);
  max-width: 820px;
  padding: 0;
  position: relative;
  transition: background 150ms ease, outline-color 150ms ease;
  border: 0;
}

.stylofact-corpus.is-dropping {
  background: var(--stylofact-accent-wash);
  outline: 2px dashed var(--stylofact-orange);
  outline-offset: 10px;
}

.stylofact-corpus-heading {
  align-items: flex-start;
  display: flex;
  gap: 15px;
  justify-content: space-between;
}

.stylofact-corpus h3 {
  font-size: 20px;
  font-weight: 500;
  letter-spacing: -.035em;
  line-height: 1;
  margin: 5px 0 0;
}

.stylofact-drop-hint {
  color: var(--stylofact-muted);
  font: 600 9px/1 'var(--ui-font-main) Next', var(--ui-font-main), sans-serif;
  letter-spacing: .08em;
  padding-top: 4px;
  text-transform: uppercase;
}

.stylofact-hint {
  color: var(--stylofact-muted);
  font: 12px/1.4 'var(--ui-font-main) Next', var(--ui-font-main), sans-serif;
  margin: 10px 0 14px;
  max-width: 590px;
}

.stylofact-corpus .stylofact-field {
  margin: 10px 0;
  max-width: 710px;
}

.stylofact-source-actions {
  align-items: center;
  color: var(--stylofact-muted);
  display: flex;
  font: 11px/1 'var(--ui-font-main) Next', var(--ui-font-main), sans-serif;
  gap: 12px;
  justify-content: space-between;
  max-width: none;
  font-size: .875rem;
}

.stylofact-source-list {
  border-top: 1px solid var(--stylofact-rule);
  list-style: none;
  margin: 0;
  max-width: none;
  padding: 0;
  border: 0;
  padding-bottom: 8px;
}

.stylofact-source-list li {
  align-items: center;
  border-bottom: 1px solid var(--stylofact-rule);
  display: flex;
  font-family: 'var(--ui-font-main) Next', var(--ui-font-main), sans-serif;
  justify-content: space-between;
  min-height: 52px;
  padding: 8px 0;
}

.stylofact-source-list strong {
  display: block;
  font-size: .9375rem;
  font-weight: 600;
}

.stylofact-source-list span {
  color: var(--stylofact-muted);
  display: block;
  font-size: .8125rem;
  margin-top: 2px;
}

.stylofact-button, .stylofact-text-button, .stylofact-icon-button, .stylofact-profile-choice button, .stylofact-version-choice button {
  cursor: pointer;
  font-family: 'var(--ui-font-main) Next', var(--ui-font-main), sans-serif;
}

.stylofact-button {
  border: 1px solid transparent;
  border-radius: 3px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0;
  min-height: 44px;
  padding: 11px 16px;
  text-transform: none;
  transition: background var(--layout-transition-fast), color var(--layout-transition-fast), border-color var(--layout-transition-fast);
  font: 700 .875rem/1 var(--stylofact-font);
}

.stylofact-button.primary {
  background: var(--stylofact-orange);
  color: var(--stylofact-on-accent);
  border-color: var(--stylofact-orange);
  min-width: 176px;
}

.stylofact-button.primary:hover:not(:disabled) {
  background: var(--stylofact-orange-deep);
  border-color: var(--stylofact-orange-deep);
}

.stylofact-button.secondary {
  background: transparent;
  border-color: var(--stylofact-rule);
  color: var(--stylofact-ink);
}

.stylofact-button.secondary:hover:not(:disabled) {
  background: var(--stylofact-ink-wash);
}

.stylofact-button:disabled, .stylofact-text-button:disabled, .stylofact-icon-button:disabled {
  cursor: not-allowed;
  opacity: .45;
}

.stylofact-icon-button {
  background: transparent;
  border: 0;
  color: var(--stylofact-red);
  font-size: 21px;
  height: 44px;
  line-height: 1;
  min-width: 44px;
  padding: 0;
}

.stylofact-text-button {
  background: transparent;
  border: 0;
  color: var(--stylofact-muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0;
  min-height: 40px;
  padding: 8px 4px;
  text-transform: none;
  font: 650 .8125rem/1 var(--stylofact-font);
}

.stylofact-text-button:hover:not(:disabled) {
  color: var(--stylofact-ink);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.stylofact-metric-strip {
  align-items: center;
  border-bottom: 1px solid var(--stylofact-rule);
  border-top: 1px solid var(--stylofact-rule);
  display: block;
  flex-wrap: wrap;
  gap: 0;
  margin: 24px 0 0;
  max-width: 820px;
}

.stylofact-metric-strip>div {
  border-right: 1px solid var(--stylofact-rule);
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 118px;
  padding: 11px 14px 11px 0;
  margin-right: 14px;
}

.stylofact-metric-strip span {
  color: var(--stylofact-muted);
  font: 700 8px/1 'var(--ui-font-main) Next', var(--ui-font-main), sans-serif;
  letter-spacing: .1em;
  text-transform: uppercase;
}

.stylofact-metric-strip strong {
  font: 600 13px/1.15 'var(--ui-font-main) Next', var(--ui-font-main), sans-serif;
}

.stylofact-metric-strip .confidence-exploratory {
  color: var(--stylofact-red);
}

.stylofact-metric-strip .confidence-provisional {
  color: var(--stylofact-warning);
}

.stylofact-metric-strip .confidence-usable {
  color: var(--stylofact-green);
}

.stylofact-metric-strip details {
  font: 600 10px/1 'var(--ui-font-main) Next', var(--ui-font-main), sans-serif;
  margin-left: auto;
  padding: 10px 0;
  position: relative;
}

.stylofact-metric-strip summary {
  cursor: pointer;
  color: var(--stylofact-orange-deep);
}

.stylofact-metric-strip pre {
  background: var(--stylofact-code-bg);
  color: var(--stylofact-code-text);
  font: 10px/1.4 ui-monospace, SFMono-Regular, Menlo, monospace;
  max-height: 230px;
  max-width: min(620px, 85cqw);
  overflow: auto;
  padding: 12px;
  position: absolute;
  right: 25px;
  white-space: pre-wrap;
  z-index: 4;
}

.stylofact-warning {
  color: var(--stylofact-red);
  font: 11px/1.35 'var(--ui-font-main) Next', var(--ui-font-main), sans-serif;
  padding: 9px 0;
}

.stylofact-navigator {
  background: transparent;
  border: 0;
  box-shadow: none;
  margin: 0 0 18px 44px;
  max-width: none;
  padding: 16px;
}

.stylofact-navigator-head, .stylofact-corpus-status-title, .stylofact-receipt>header, .stylofact-source-viewer>header {
  align-items: flex-start;
  display: flex;
  gap: 12px;
  justify-content: space-between;
}

.stylofact-navigator-head h3, .stylofact-receipt h3, .stylofact-source-viewer h3 {
  font-size: 21px;
  font-weight: 500;
  letter-spacing: -.035em;
  margin: 3px 0 0;
}

.stylofact-navigator>.stylofact-hint {
  margin: 10px 0 13px;
}

.stylofact-navigator-empty {
  border: 1px dashed var(--stylofact-rule);
  color: var(--stylofact-muted);
  font: 12px/1.4 'var(--ui-font-main) Next', var(--ui-font-main), sans-serif;
  padding: 13px;
}

.stylofact-corpus-status {
  border-top: 1px solid var(--stylofact-rule);
  padding: 20px 0 8px;
}

.stylofact-corpus-status-title>div {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.stylofact-corpus-status-title strong {
  font: 700 .9375rem/1.3 var(--stylofact-font);
}

.stylofact-corpus-status-title div span {
  color: var(--stylofact-muted);
  font: .75rem/1.3 var(--stylofact-font);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.stylofact-index-state {
  border: 0;
  color: var(--stylofact-warning);
  font: 650 .8125rem/1.3 var(--stylofact-font);
  letter-spacing: 0;
  padding: 0;
  text-transform: none;
  white-space: nowrap;
}

.stylofact-index-state.state-ready, .stylofact-index-state.state-lexical-ready {
  color: var(--stylofact-green);
}

.stylofact-index-state.state-error, .stylofact-index-state.state-stale {
  color: var(--stylofact-red);
}

.stylofact-corpus-counts {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 20px;
  margin-top: 10px;
}

.stylofact-corpus-counts span {
  color: var(--stylofact-muted);
  font: .8125rem/1.3 var(--stylofact-font);
}

.stylofact-corpus-counts strong {
  color: var(--stylofact-ink);
}

.stylofact-index-progress {
  background: var(--stylofact-ink-wash);
  height: 4px;
  margin-top: 10px;
  overflow: hidden;
  appearance: none;
  border: 0;
  display: block;
  margin: 12px 0 0;
  width: 100%;
}

.stylofact-index-progress span {
  background: var(--stylofact-orange);
  display: block;
  height: 100%;
  transition: width .3s ease;
}

.stylofact-corpus-status>p {
  color: var(--stylofact-muted);
  font: .8125rem/1.45 var(--stylofact-font);
  margin: 8px 0 0;
}

.stylofact-corpus-status-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-top: 7px;
  margin: 0;
  padding-bottom: 8px;
}

.stylofact-text-button.danger {
  color: var(--stylofact-red);
}

.stylofact-receipt-overlay {
  align-items: center;
  background: rgba(41, 46, 91, 0.72);
  display: flex;
  inset: 0;
  justify-content: center;
  padding: 28px;
  position: fixed;
  z-index: 1000;
}

.stylofact-receipt, .stylofact-source-viewer {
  background: var(--stylofact-paper);
  border: 1px solid var(--stylofact-rule);
  box-shadow: 0 20px 60px rgba(23, 25, 65, 0.24);
  color: var(--stylofact-ink);
  max-height: min(820px, calc(100vh - 56px));
  max-width: 900px;
  overflow: auto;
  padding: 24px;
  width: min(900px, calc(100vw - 56px));
}

.stylofact-receipt-summary {
  border-bottom: 1px solid var(--stylofact-rule);
  border-top: 1px solid var(--stylofact-rule);
  display: grid;
  gap: 1px;
  grid-template-columns: repeat(5, 1fr);
  margin-top: 15px;
}

.stylofact-receipt-summary div {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px 6px;
}

.stylofact-receipt-summary span, .stylofact-conversation-context article>span {
  color: var(--stylofact-muted);
  font: 700 8px/1 'var(--ui-font-main) Next', var(--ui-font-main), sans-serif;
  letter-spacing: .07em;
  text-transform: uppercase;
}

.stylofact-receipt-summary strong {
  font: 600 12px/1.2 'var(--ui-font-main) Next', var(--ui-font-main), sans-serif;
  text-transform: capitalize;
}

.stylofact-receipt-section {
  border-bottom: 1px solid var(--stylofact-rule);
  padding: 15px 0;
}

.stylofact-receipt-section h4 {
  font: 600 13px/1.2 'var(--ui-font-main) Next', var(--ui-font-main), sans-serif;
  margin: 0 0 9px;
}

.stylofact-receipt-section>p {
  font: 13px/1.45 Georgia, serif;
  margin: 0 0 9px;
}

.stylofact-query-row {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin: 5px 0;
}

.stylofact-query-row code {
  background: var(--stylofact-ink-wash);
  color: var(--stylofact-muted);
  font-size: 10px;
  padding: 5px 7px;
}

.stylofact-receipt-candidate {
  background: var(--stylofact-surface);
  border-left: 2px solid var(--stylofact-green);
  margin-top: 8px;
  padding: 10px 12px;
}

.stylofact-receipt-candidate>div {
  display: flex;
  gap: 10px;
  justify-content: space-between;
}

.stylofact-receipt-candidate>div strong {
  font: 600 11px/1.2 'var(--ui-font-main) Next', var(--ui-font-main), sans-serif;
}

.stylofact-receipt-candidate>div span {
  color: var(--stylofact-muted);
  font: 9px/1.2 ui-monospace, SFMono-Regular, Menlo, monospace;
}

.stylofact-receipt-candidate p {
  font: 13px/1.45 Georgia, serif;
  margin: 8px 0 3px;
  white-space: pre-wrap;
}

.stylofact-receipt-omitted, .stylofact-receipt-raw {
  border-bottom: 1px solid var(--stylofact-rule);
  padding: 13px 0;
}

.stylofact-receipt-omitted summary, .stylofact-receipt-raw summary {
  color: var(--stylofact-orange-deep);
  cursor: pointer;
  font: 700 10px/1.2 'var(--ui-font-main) Next', var(--ui-font-main), sans-serif;
  text-transform: uppercase;
}

.stylofact-receipt-omitted div {
  display: flex;
  gap: 10px;
  justify-content: space-between;
  padding: 6px 0;
}

.stylofact-receipt-omitted strong, .stylofact-receipt-omitted span {
  font: 10px/1.3 'var(--ui-font-main) Next', var(--ui-font-main), sans-serif;
}

.stylofact-receipt-omitted span {
  color: var(--stylofact-muted);
  text-align: right;
}

.stylofact-receipt-raw pre {
  background: var(--stylofact-code-bg);
  color: var(--stylofact-code-text);
  font: 10px/1.4 ui-monospace, SFMono-Regular, Menlo, monospace;
  max-height: 380px;
  overflow: auto;
  padding: 12px;
  white-space: pre-wrap;
}

.stylofact-conversation-context {
  display: flex;
  flex-direction: column;
  gap: 9px;
  margin-top: 16px;
}

.stylofact-conversation-context article {
  border: 1px solid var(--stylofact-rule);
  margin-left: 8%;
  padding: 11px 13px;
}

.stylofact-conversation-context article.role-user {
  background: var(--stylofact-surface);
  margin-left: 0;
  margin-right: 8%;
}

.stylofact-conversation-context article.is-evidence {
  border-color: var(--stylofact-green);
  box-shadow: 3px 3px 0 var(--stylofact-success-wash);
}

.stylofact-conversation-context p {
  font: 13px/1.45 Georgia, serif;
  margin: 7px 0 0;
  white-space: pre-wrap;
