}

.stylofact-run-head {
  align-items: baseline;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.stylofact-run-head strong {
  font: 700 12px/1.3 var(--stylofact-font);
}

.stylofact-run-head span {
  color: var(--stylofact-muted);
  font: 11px/1.3 var(--stylofact-font);
}

.stylofact-run-status {
  font: 700 10px/1 var(--stylofact-font);
  font-style: normal;
  letter-spacing: .06em;
  margin-left: auto;
  text-transform: uppercase;
}

.stylofact-run-status.status-failed {
  color: var(--stylofact-red);
}

.stylofact-run-status.status-completed {
  color: var(--stylofact-green, #25758a);
}

.stylofact-run-error {
  color: var(--stylofact-red);
  font: 12px/1.45 var(--stylofact-font);
  margin: 0;
  overflow-wrap: anywhere;
}

.stylofact-run-next {
  color: var(--stylofact-ink);
  font: 12px/1.45 var(--stylofact-font);
  margin: 0;
}

.stylofact-run-next strong {
  font-size: 10px;
  letter-spacing: .04em;
  text-transform: uppercase;
}

.stylofact-run .stylofact-text-button {
  justify-self: start;
}

.theme-studio {
  --ts-ink: #ede9da;
  --ts-soft: #95a4a4;
  --ts-muted: #5e6e74;
  --ts-line: rgba(237, 233, 218, 0.13);
  --ts-line-strong: rgba(237, 233, 218, 0.25);
  --ts-accent: #87b7bd;
  --ts-accent-soft: rgba(135, 183, 189, 0.16);
  position: fixed;
  z-index: 200000000;
  inset: 0 0 0 auto;
  min-width: 300px;
  max-width: 480px;
  display: flex;
  flex-direction: column;
  color: var(--ts-ink);
  background: #2c315e;
  border-left: 1px solid var(--ts-line-strong);
  box-shadow: -18px 0 55px rgba(23, 25, 65, 0.38);
  font-family: "Avenir Next", Avenir, sans-serif;
  letter-spacing: 0;
  -webkit-app-region: no-drag;
}

.theme-studio *, .theme-studio *::before, .theme-studio *::after {
  box-sizing: border-box;
}

.theme-studio button, .theme-studio input, .theme-studio select {
  font: inherit;
}

.theme-studio button {
  color: inherit;
}

.theme-studio button:focus-visible, .theme-studio input:focus-visible, .theme-studio select:focus-visible, .theme-studio summary:focus-visible {
  outline: 2px solid var(--ts-accent);
  outline-offset: 2px;
}

.theme-studio-resize {
  position: absolute;
  z-index: 2;
  inset: 0 auto 0 -5px;
  width: 10px;
  cursor: ew-resize;
}

.theme-studio-resize::after {
  content: "";
  position: absolute;
  inset: 0 auto 0 4px;
  width: 1px;
  background: transparent;
}

.theme-studio-resize:hover::after {
  background: var(--ts-accent);
}

.theme-studio-header {
  flex: 0 0 auto;
  padding: 17px 16px 11px;
  border-bottom: 1px solid var(--ts-line);
  background: #2e3360;
}

.theme-studio-title-row {
  display: grid;
  grid-template-columns: 1fr auto auto;
  align-items: center;
  gap: 10px;
  margin-bottom: 13px;
}

.theme-studio-title-row>div {
  display: flex;
  flex-direction: column;
}

.theme-studio-title-row strong {
  font-family: Optima, Candara, sans-serif;
  font-size: 20px;
  font-weight: 500;
  letter-spacing: -.02em;
}

.theme-studio-kicker, .theme-studio-intro>span, .theme-studio-selection-heading>span {
  color: var(--ts-muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .15em;
}

.theme-studio-dirty-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--ts-muted);
}

.theme-studio-dirty-dot.active {
  background: var(--ts-accent);
  box-shadow: 0 0 0 4px var(--ts-accent-soft);
}

.theme-studio-theme-select {
  width: 100%;
  height: 31px;
  padding: 0 28px 0 9px;
  border: 1px solid var(--ts-line-strong);
  border-radius: 3px;
  color: var(--ts-ink);
  background: #2a2f5b;
  font-size: 11px;
}

.theme-studio-command-row {
  display: flex;
  align-items: center;
  gap: 3px;
  margin-top: 8px;
}

.theme-studio-command-row>button, .theme-studio-more>summary {
  min-height: 25px;
  padding: 0 7px;
  border: 0;
  border-radius: 3px;
  color: var(--ts-soft);
  background: transparent;
  font-size: 10px;
  cursor: pointer;
}

.theme-studio-command-row>button:hover, .theme-studio-more>summary:hover {
  color: var(--ts-ink);
  background: rgba(254, 251, 241, 0.06);
}

.theme-studio-command-row>button:active, .theme-studio-more>summary:active, .theme-studio-selected-actions button:active, .theme-studio-surprise:active {
  transform: translateY(1px);
}

.theme-studio-command-row>button:disabled {
  opacity: .28;
  cursor: default;
}

.theme-studio-command-row .theme-studio-save {
  color: #2c315e;
  background: var(--ts-accent);
  font-weight: 700;
}

.theme-studio-command-spacer {
  flex: 1;
}

.theme-studio-icon-btn {
  display: grid;
  place-items: center;
  min-width: 25px;
  padding: 0 !important;
  border: 0;
  background: transparent;
  cursor: pointer;
}

.theme-studio-file-input {
  display: none;
}

.theme-studio-more {
  position: relative;
}

.theme-studio-more>summary {
  display: grid;
  place-items: center;
  min-width: 29px;
  list-style: none;
}

.theme-studio-more>summary::-webkit-details-marker {
  display: none;
}

.theme-studio-more>div {
  position: absolute;
  z-index: 3;
  top: calc(100% + 6px);
  right: 0;
  width: 128px;
  padding: 5px;
  border: 1px solid var(--ts-line-strong);
  background: #323765;
  box-shadow: 0 14px 35px rgba(23, 25, 65, 0.4);
}

.theme-studio-more button {
  display: block;
  width: 100%;
  padding: 7px 8px;
  border: 0;
  color: var(--ts-soft);
  background: transparent;
  font-size: 10px;
  text-align: left;
  cursor: pointer;
}

.theme-studio-more button:hover {
  color: var(--ts-ink);
  background: rgba(254, 251, 241, 0.06);
}

.theme-studio-more button.danger {
  color: #e07672;
}

.theme-studio-more button:disabled {
  opacity: .3;
}

.theme-studio-name-action, .theme-studio-dirty-guard {
  padding: 10px 16px;
  border-bottom: 1px solid var(--ts-line);
  background: #323869;
}

.theme-studio-name-action label, .theme-studio-dirty-guard>span {
  display: block;
  margin-bottom: 6px;
  color: var(--ts-soft);
  font-size: 10px;
}

.theme-studio-name-action>div, .theme-studio-dirty-guard>div {
  display: flex;
