}

.theme-studio-name-action input {
  flex: 1;
  min-width: 0;
  height: 28px;
  padding: 0 8px;
  border: 1px solid var(--ts-line-strong);
  border-radius: 2px;
  color: var(--ts-ink);
  background: #2a2f5b;
  font-size: 11px;
}

.theme-studio-name-action button, .theme-studio-dirty-guard button {
  min-height: 27px;
  padding: 0 8px;
  border: 1px solid var(--ts-line);
  border-radius: 2px;
  color: var(--ts-soft);
  background: transparent;
  font-size: 9px;
  white-space: nowrap;
  cursor: pointer;
}

.theme-studio-nav {
  display: grid;
  grid-template-columns: repeat(3, 1fr) 1.18fr;
  flex: 0 0 auto;
  padding: 0 10px;
  border-bottom: 1px solid var(--ts-line);
}

.theme-studio-nav button {
  position: relative;
  height: 38px;
  border: 0;
  border-bottom: 2px solid transparent;
  color: var(--ts-muted);
  background: transparent;
  font-size: 10px;
  cursor: pointer;
}

.theme-studio-nav button:hover {
  color: var(--ts-soft);
}

.theme-studio-nav button.active {
  color: var(--ts-ink);
  border-bottom-color: var(--ts-accent);
}

.theme-studio-nav button span {
  position: absolute;
  top: 9px;
  right: 8px;
