  overflow: auto;
  scrollbar-color: var(--ts-line-strong) transparent;
}

.theme-studio-view {
  min-height: 100%;
  padding: 15px 16px 36px;
}

.theme-studio-intro {
  margin: 2px 0 18px;
}

.theme-studio-intro p {
  max-width: 36ch;
  margin: 7px 0 0;
  color: var(--ts-soft);
  font-size: 11px;
  line-height: 1.55;
}

.theme-studio-segmented {
  display: grid;
  grid-template-columns: 1fr 1fr;
  padding: 2px;
  margin-bottom: 18px;
  background: #292d59;
  border: 1px solid var(--ts-line);
}

.theme-studio-segmented button {
  height: 27px;
  border: 0;
  color: var(--ts-muted);
  background: transparent;
  font-size: 10px;
  text-transform: capitalize;
