  justify-content: center;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
}

.jr-action svg {
  width: 22px;
  height: 22px;
}

.jr-action:hover:not(:disabled), .jr-action.is-active {
  border-color: rgba(254, 251, 241, 0.45);
  color: #fefbf1;
  box-shadow: 0 0 14px rgba(254, 251, 241, 0.18);
}

.jr-action.is-stub {
  opacity: 0.55;
  cursor: default;
}

.jr-action:disabled:not(.jr-action--current) {
  opacity: 0.35;
  cursor: default;
}

.jr-action--danger:not(:disabled) {
  color: #e2b33d;
  border-color: rgba(240, 106, 103, 0.35);
}

.jr-action--danger:hover:not(:disabled), .jr-action--danger:focus-visible {
  color: #fefbf1;
  background: rgba(179, 59, 0, 0.72);
  border-color: rgba(225, 177, 55, 0.8);
  box-shadow: 0 0 14px rgba(240, 87, 88, 0.28);
}

.jr-action--current {
  background: #fefbf1;
  border-color: #fefbf1;
  color: #171941;
  cursor: default;
}

.jr-action--current:not(:disabled) {
  cursor: pointer;
}

.jr-searchbar {
  overflow: hidden;
  max-width: 0;
  opacity: 0;
  transition: max-width 0.22s ease, opacity 0.18s ease;
}

.jr-searchbar.is-open {
  max-width: 280px;
  opacity: 1;
}

.jr-searchbar__input {
  width: 250px;
}

.jr-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 26px 24px;
  max-width: 1480px;
  margin: 0 auto;
  justify-items: center;
  perspective: 1000px;
}

.jr-empty {
  grid-column: 1 / -1;
  margin-top: 80px;
  color: rgba(254, 251, 241, 0.4);
  font-size: 15px;
  text-align: center;
  user-select: none;
}

.jr-card {
  appearance: none;
  position: relative;
  border: 0;
  padding: 0;
  background: none;
  cursor: pointer;
  width: 100%;
  max-width: 200px;
  aspect-ratio: 3 / 4;
  border-radius: 10px;
  outline: none;
}

.jr-card__cover {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 20px;
  display: block;
  filter: brightness(0.62) saturate(.8);
  transition: all .2s ease, transform .8s cubic-bezier(.4, .8, .2, 1);
  transform-style: preserve-3d;
  transform: rotateX(20deg)rotateY(10deg)translateZ(0px)skewX(-10deg)scale(.86);
  box-shadow: 3px 2px .1px rgba(255, 250, 238, 0.69), 3px 3px 1px rgba(254, 251, 241, 0.579), 5px 6px 4px rgba(23, 25, 65, 0.73), 0 0 10px rgba(254, 251, 241, 0), 0 0 1px rgba(23, 25, 65, 0);
}

.jr-card__plaque, .jr-card__name, .jr-card__count {
  transition: all .5s ease;
}

.jr-card__cover--missing {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: 10px;
  background: linear-gradient(160deg, #2d3260, #242854);
  border: 1px solid rgba(254, 251, 241, 0.08);
}

.jr-card:hover .jr-card__cover {
  filter: brightness(.81) saturate(.8);
}

.jr-card.is-selected .jr-card__cover {
  box-shadow: 0 0 2px #fefbf1, 0 0 80px rgb(74, 108, 118), inset 0 0 30px #171941;
  filter: brightness(1)saturate(1);
  transform: rotateX(0deg)rotateY(0deg)translateZ(0px)scale(1.2);
}

.jr-card__plaque {
  position: absolute;
  top: 98%;
  left: 50%;
  transform: translateX(-50%);
  width: 86%;
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: stretch;
  pointer-events: none;
}

.jr-card.is-selected .jr-card__plaque {
  opacity: 1;
  top: 58%;
}

.jr-card.is-selected .jr-card__count, .jr-card.is-selected .jr-card__name {
  opacity: 1;
  background: #171941;
}

.jr-card__name, .jr-card__count {
  display: block;
  background: transparent;
  border: 2px solid rgba(0, 142, 222, 0);
  box-shadow: inset 0 0 6px transparent;
  border-radius: 6px;
  color: #fefbf1;
  text-align: center;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.jr-card__name {
  font-family: var(--ui-font-main), Jost, 'SF Pro', system-ui, sans-serif;
  font-size: clamp(18px, 2vw, 28px);
  font-weight: 400;
  padding: 8px 10px;
  opacity: .4;
  box-shadow: inset 0 0 6px transparent;
}

.jr-card:hover .jr-card__name {
  opacity: 1;
}

.jr-card__count {
  font-family: Georgia, 'Times New Roman', serif;
  font-size: clamp(13px, 1.2vw, 18px);
  padding: 4px 10px;
  margin: 0 8%;
  opacity: 0;
}

.jr-input {
  appearance: none;
  background: rgba(254, 251, 241, 0.06);
  border: 1px solid rgba(254, 251, 241, 0.16);
  border-radius: 8px;
  color: #fefbf1;
  font-size: 14px;
  padding: 9px 12px;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
  box-sizing: border-box;
}

.jr-input:focus {
  border-color: rgba(118, 188, 197, 0.8);
  box-shadow: 0 0 10px rgba(118, 188, 197, 0.25);
}

.jr-input::placeholder {
  color: rgba(254, 251, 241, 0.32);
}

.jr-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 24;
  background: rgba(23, 25, 65, 0.72);
  backdrop-filter: blur(6px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 32px;
}

.jr-modal {
  width: min(640px, 100%);
  max-height: 86vh;
  overflow-y: auto;
  background: #272c58;
  border: 1px solid rgba(254, 251, 241, 0.14);
  border-radius: 14px;
  box-shadow: 0 24px 80px rgba(23, 25, 65, 0.8), 0 0 36px rgba(118, 188, 197, 0.1);
  padding: 26px 28px 22px;
  box-sizing: border-box;
}

.jr-modal__title {
  margin: 0 0 18px;
  font-family: 'SF Pro', system-ui, sans-serif;
  font-size: 20px;
  font-weight: 600;
  letter-spacing: 0.01em;
  text-transform: lowercase;
  color: #fefbf1;
}

.jr-field {
  display: block;
  margin-bottom: 16px;
}

.jr-field__label {
  display: block;
  margin-bottom: 7px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(254, 251, 241, 0.45);
}

.jr-field .jr-input {
  width: 100%;
}

.jr-tagbox {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  background: rgba(254, 251, 241, 0.06);
  border: 1px solid rgba(254, 251, 241, 0.16);
  border-radius: 8px;
  padding: 6px 8px;
  cursor: text;
  min-height: 40px;
  box-sizing: border-box;
}

.jr-tagbox:focus-within {
  border-color: rgba(118, 188, 197, 0.8);
  box-shadow: 0 0 10px rgba(118, 188, 197, 0.25);
}

.jr-tag {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background: rgba(118, 188, 197, 0.16);
  border: 1px solid rgba(118, 188, 197, 0.45);
  border-radius: 999px;
  color: #ede5cb;
  font-size: 12.5px;
  padding: 3px 6px 3px 10px;
  white-space: nowrap;
}

.jr-tag__x {
  appearance: none;
  border: 0;
  background: none;
  color: rgba(237, 229, 203, 0.7);
  font-size: 14px;
  line-height: 1;
  cursor: pointer;
  padding: 0 3px;
}

.jr-tag__x:hover {
  color: #fefbf1;
}

.jr-tagbox__input {
  appearance: none;
  flex: 1;
  min-width: 120px;
  background: none;
  border: 0;
  outline: none;
  color: #fefbf1;
  font-size: 14px;
  padding: 4px 2px;
}

.jr-tagbox__input::placeholder {
  color: rgba(254, 251, 241, 0.32);
}

.jr-picker {
  display: flex;
  gap: 10px;
  overflow-x: auto;
  padding: 4px 2px 8px;
  scrollbar-width: thin;
}

.jr-swatch {
  appearance: none;
  flex: 0 0 auto;
  padding: 0;
  border: 2px solid transparent;
  border-radius: 8px;
  background: none;
  cursor: pointer;
  transition: border-color 0.12s ease, box-shadow 0.12s ease, transform 0.12s ease;
}

.jr-swatch img {
  display: block;
  border-radius: 6px;
  object-fit: cover;
  width: 74px;
  height: 98px;
}

.jr-picker--pages .jr-swatch img {
  width: 74px;
  height: 98px;
}

.jr-swatch:hover {
  transform: translateY(-2px);
}

.jr-swatch.is-selected {
  border-color: rgba(118, 188, 197, 0.95);
  box-shadow: 0 0 12px rgba(118, 188, 197, 0.5);
}

.jr-modal__actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 6px;
}

.jr-btn {
  appearance: none;
  border: 1px solid rgba(254, 251, 241, 0.2);
  background: rgba(254, 251, 241, 0.05);
  color: rgba(254, 251, 241, 0.85);
  border-radius: var(--ui-border-radius);
  font-size: 13.5px;
  opacity: .6;
  text-transform: lowercase;
  padding: 1px 1px;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
}

.jr-btn:hover:not(:disabled) {
  opacity: 1;
  border-color: rgba(254, 251, 241, 0.45);
  background: rgba(254, 251, 241, 0.1);
}

.jr-btn--primary {
  background: rgba(0, 142, 222, 0.22);
  border-color: rgba(118, 188, 197, 0.7);
  color: #faf4e4;
}

.jr-btn--primary:hover:not(:disabled) {
  background: rgba(0, 142, 222, 0.36);
  box-shadow: 0 0 14px rgba(118, 188, 197, 0.35);
}

.jr-btn:disabled {
  opacity: 0.45;
  cursor: default;
}

.jr-templates {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(168px, 1fr));
  gap: 10px;
}

.jr-template {
  appearance: none;
  display: flex;
  flex-direction: column;
  gap: 4px;
  text-align: left;
  background: rgba(254, 251, 241, 0.05);
  border: 1px solid rgba(254, 251, 241, 0.14);
  border-radius: 10px;
  padding: 12px 14px;
  cursor: pointer;
  transition: border-color 0.13s ease, box-shadow 0.13s ease, background 0.13s ease;
}

.jr-template:hover {
  border-color: rgba(254, 251, 241, 0.35);
}

.jr-template.is-selected {
  border-color: rgba(118, 188, 197, 0.95);
  background: rgba(0, 142, 222, 0.12);
  box-shadow: 0 0 12px rgba(118, 188, 197, 0.35);
}

.jr-template__name {
  font-family: var(--ui-font-main), Jost, 'SF Pro', system-ui, sans-serif;
  font-size: 15px;
  color: #fefbf1;
}

.jr-template__tagline {
  font-size: 11.5px;
  line-height: 1.35;
  color: rgba(254, 251, 241, 0.55);
}

.jr-template__count {
  margin-top: 2px;
  font-size: 10.5px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(118, 188, 197, 0.75);
}

.jr-import {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.jr-import__file {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.jr-import__head {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.jr-import__hint {
  font-size: 11.5px;
  line-height: 1.35;
  color: rgba(254, 251, 241, 0.45);
}

.jr-import__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.jr-import__row {
  display: flex;
  align-items: center;
  gap: 10px;
  background: rgba(254, 251, 241, 0.05);
  border: 1px solid rgba(254, 251, 241, 0.14);
  border-radius: 10px;
  padding: 8px 10px;
}

.jr-import__meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  flex: 1;
}

.jr-import__name {
  font-family: var(--ui-font-main), Jost, 'SF Pro', system-ui, sans-serif;
  font-size: 13px;
  color: #fefbf1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.jr-import__preview {
  font-size: 10.5px;
  letter-spacing: 0.04em;
  color: rgba(118, 188, 197, 0.75);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.jr-import__targets {
  display: flex;
  flex-shrink: 0;
  border: 1px solid rgba(254, 251, 241, 0.16);
  border-radius: 8px;
  overflow: hidden;
}

.jr-import__target {
  appearance: none;
  background: transparent;
  border: 0;
  border-right: 1px solid rgba(254, 251, 241, 0.12);
  color: rgba(254, 251, 241, 0.6);
  font-size: 11px;
  letter-spacing: 0.04em;
  padding: 6px 10px;
  cursor: pointer;
  transition: background 0.13s ease, color 0.13s ease;
}

.jr-import__target:last-child {
  border-right: 0;
}

.jr-import__target:hover {
  background: rgba(254, 251, 241, 0.08);
  color: #fefbf1;
}

.jr-import__target.is-selected {
  background: rgba(0, 142, 222, 0.22);
  color: #fefbf1;
  box-shadow: inset 0 0 10px rgba(118, 188, 197, 0.25);
}

.jr-import__drop {
  appearance: none;
  flex-shrink: 0;
  background: transparent;
  border: 0;
  color: rgba(254, 251, 241, 0.4);
  font-size: 16px;
  line-height: 1;
  padding: 2px 4px;
  cursor: pointer;
  transition: color 0.13s ease;
}

.jr-import__drop:hover {
  color: #6ebdc8;
}

.jr-import__skipped {
  margin: 0;
  font-size: 11px;
  line-height: 1.4;
  color: rgba(226, 207, 145, 0.8);
}

.jv-root {
  position: relative;
  width: 100%;
  height: 100%;
  isolation: isolate;
  overflow: hidden;
  padding: 10px 16px 12px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.jv-root::-webkit-scrollbar {
  display: none;
}

.jv-backdrop {
  position: absolute;
  inset: 0px;
  z-index: -1;
  background-size: cover;
  background-position: center;
  filter: blur(10px) brightness(0.7) saturate(1);
  pointer-events: none;
}

.jv-backdrop::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, rgba(23, 25, 65, 0.25) 0%, rgba(23, 25, 65, 0.6) 100%), rgba(23, 25, 65, 0.25);
}

.jv-topbar {
  display: flex;
  align-items: center;
  gap: 12px;
}

.jv-topbar .jr-btn {
  padding: 5px 13px;
  font-size: 13px;
}

.jv-title {
  margin: 0;
  flex: 1;
  font-family: var(--ui-font-main), Jost, 'SF Pro', system-ui, sans-serif;
  font-size: 22px;
  font-weight: 400;
  color: #fefbf1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.jv-pageno {
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 13px;
  color: rgba(254, 251, 241, 0.45);
}

.jv-book {
  display: flex;
  align-items: stretch;
  gap: 0px;
  flex: 1;
  min-height: 0;
  position: relative;
}

.jv-nav {
  appearance: none;
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  z-index: 5;
  width: 18px;
  height: 72%;
  border-radius: 10px 0 0 10px;
  border: 1px solid rgba(254, 251, 241, 0.14);
  background: rgba(254, 251, 241, 0.04);
  color: rgba(254, 251, 241, 0.8);
  font-size: 18px;
  cursor: pointer;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.jv-nav:hover:not(:disabled) {
  border-color: rgba(254, 251, 241, 0.4);
  box-shadow: 0 0 12px rgba(254, 251, 241, 0.15);
}

.jv-nav:disabled {
  opacity: 0.25;
  cursor: default;
}

.jv-nav.right {
  border-radius: 0 10px 10px 0;
  left: auto;
  right: 0;
}

.jv-bookport {
  flex: 1;
  min-width: 0;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.jv-bookscale {
  flex: none;
  position: relative;
  transform-origin: center center;
}

.jv-spread {
  width: 100%;
  height: 100%;
  display: grid;
  grid-template-columns: 1fr 3px 1fr;
  background: #272c58;
  border: 1px solid rgba(254, 251, 241, 0.12);
  border-radius: 12px;
  box-shadow: 0 22px 70px rgba(23, 25, 65, 0.7);
  overflow: hidden;
  box-sizing: border-box;
}

.jv-spread--single {
  grid-template-columns: 1fr;
}

.jv-scrollstack {
  min-width: 0;
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
}

.jv-scrollstack::-webkit-scrollbar {
  display: none;
}

.jv-scrollstack__page {
  flex: none;
}

.jv-scrollstack__page>.jv-page {
  height: 100%;
  box-sizing: border-box;
}

.jv-scrollstack__ghost {
  flex: none;
}

.jvb__scrolltoggle {
  appearance: none;
  padding: 6px 14px;
  border-radius: 999px;
  border: 1px solid rgba(254, 251, 241, 0.22);
  background: rgba(23, 25, 65, 0.5);
  color: rgba(254, 251, 241, 0.8);
  font-family: var(--ui-font-main), Jost, system-ui, sans-serif;
  font-size: 12px;
  cursor: pointer;
  white-space: nowrap;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, color 0.15s ease;
}

.jvb__scrolltoggle:hover {
  border-color: rgba(92, 208, 197, 0.8);
  color: #fefbf1;
}

.jvb__scrolltoggle.is-on {
  border-color: rgba(118, 188, 197, 0.6);
  box-shadow: 0 0 10px rgba(118, 188, 197, 0.25);
  color: #faf4e4;
}

.jv-root.is-narrow {
  padding: 8px 10px 12px;
}

.jv-root.is-narrow .jvs-toggle {
  display: none;
}

.jv-root.is-narrow .jv-topbar {
  gap: 10px;
}

.jv-root.is-narrow .jv-pageno {
  display: none;
}

.jv-root.is-narrow .jvb__tagswrap {
  width: 90px;
}

.jv-root.is-narrow .jvb__tags.is-expanded {
  width: 260px;
}

.jv-spine {
  background: linear-gradient(to right, rgba(23, 25, 65, 0.55), rgba(254, 251, 241, 0.06), rgba(23, 25, 65, 0.55));
}

.jv-page {
  position: relative;
  background-size: 100% 100%;
  background-position: center;
  padding: 11px;
  box-sizing: border-box;
  display: flex;
  min-height: 0;
  min-width: 0;
}

.jv-page--empty {
  background: linear-gradient(160deg, #2c315f, #262a56);
}

.jv-page__paper {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
  background: rgba(38, 42, 87, 0.78);
  backdrop-filter: blur(5px);
  border: 1px solid rgba(254, 251, 241, 0.2);
  border-radius: 10px;
  padding: 12px 14px;
  overflow-y: auto;
}

.jv-page__paper::-webkit-scrollbar {
  width: 6px;
}

.jv-page__paper::-webkit-scrollbar-thumb {
  background: rgba(254, 251, 241, 0.15);
  border-radius: 3px;
}

.jv-page__paper--fixed, .jv-page__paper--fixed .jv-page__body {
  overflow: hidden;
}

.jv-page__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  border-bottom: 1px solid rgba(254, 251, 241, 0.12);
  padding-bottom: 6px;
  margin-bottom: 9px;
}

.jv-page__head h3 {
  margin: 0;
  font-family: var(--ui-font-main), Jost, 'SF Pro', system-ui, sans-serif;
  font-size: 17px;
  font-weight: 500;
  color: #fefbf1;
}

.jv-page__titleedit {
  flex: 1 1 auto;
  min-width: 0;
  margin: 0;
  padding: 0 2px;
  border: 0;
  border-radius: 3px;
  background: transparent;
  outline: none;
  font-family: var(--ui-font-main), Jost, 'SF Pro', system-ui, sans-serif;
  font-size: 17px;
  font-weight: 500;
  color: #fefbf1;
}

.jv-page__titleedit::placeholder {
  color: rgba(254, 251, 241, 0.35);
}

.jv-page__titleedit:hover {
  background: rgba(254, 251, 241, 0.06);
}

.jv-page__titleedit:focus {
  background: rgba(254, 251, 241, 0.09);
}

.jv-page__type {
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(118, 188, 197, 0.7);
  white-space: nowrap;
}

.jv-page__body {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
  color: rgba(254, 251, 241, 0.85);
  font-size: 13.5px;
  line-height: 1.5;
}

.jv-dashboard {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
  align-content: start;
}

.jv-widget {
  display: flex;
  flex-direction: column;
  gap: 3px;
  background: rgba(254, 251, 241, 0.05);
  border: 1px solid rgba(254, 251, 241, 0.1);
  border-radius: 8px;
  padding: 10px 12px;
}

.jv-widget--progress {
  grid-column: 1 / -1;
}

.jv-widget__value {
  font-family: var(--ui-font-main), Jost, 'SF Pro', system-ui, sans-serif;
  font-size: 22px;
  color: #fefbf1;
}

.jv-widget__label {
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(254, 251, 241, 0.5);
}

.jv-widget__hint {
  font-size: 11px;
  color: rgba(254, 251, 241, 0.35);
}

.jv-bar {
  height: 8px;
  border-radius: 4px;
  background: rgba(254, 251, 241, 0.08);
  overflow: hidden;
}

.jv-bar__fill {
  height: 100%;
  min-width: 2px;
  border-radius: 4px;
  background: linear-gradient(90deg, rgba(118, 188, 197, 0.9), rgba(40, 213, 201, 0.85));
}

.jv-dashboard__note {
  grid-column: 1 / -1;
  margin: 4px 0 0;
  font-family: Georgia, 'Times New Roman', serif;
  font-style: italic;
  font-size: 12.5px;
  color: rgba(254, 251, 241, 0.5);
}

.jv-tracker table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12.5px;
}

.jv-tracker th {
  text-align: left;
  font-size: 10.5px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(118, 188, 197, 0.75);
  border-bottom: 1px solid rgba(254, 251, 241, 0.16);
  padding: 4px 8px 6px 2px;
}

.jv-tracker td {
  border-bottom: 1px solid rgba(254, 251, 241, 0.07);
  padding: 6px 8px 6px 2px;
  color: rgba(254, 251, 241, 0.85);
}

.jv-tracker__draft input {
  width: 100%;
  box-sizing: border-box;
  background: none;
  border: 0;
  border-bottom: 1px dashed rgba(254, 251, 241, 0.2);
  outline: none;
  color: #fefbf1;
  font-size: 12.5px;
  padding: 3px 0;
  border-radius: 0;
}

.jv-tracker__draft input::placeholder {
  color: rgba(254, 251, 241, 0.25);
}

.jv-minibtn {
  appearance: none;
  margin-top: 10px;
  align-self: flex-start;
  background: none;
  border: 1px solid rgba(254, 251, 241, 0.18);
  border-radius: 6px;
  color: rgba(254, 251, 241, 0.6);
  font-size: 11.5px;
  text-transform: lowercase;
  padding: 4px 10px;
  cursor: pointer;
}

.jv-minibtn:hover {
  border-color: rgba(254, 251, 241, 0.4);
  color: #fefbf1;
}

.jv-todo {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.jv-todo__item {
  display: flex;
  align-items: center;
  gap: 9px;
  cursor: pointer;
}

.jv-todo__item input {
  margin-top: 3px;
  accent-color: rgb(118, 188, 197);
}

.jv-todo__item.is-done span {
  text-decoration: line-through;
  color: rgba(254, 251, 241, 0.35);
}

.jv-todo__add input {
  width: 100%;
  box-sizing: border-box;
  background: none;
  border: 0;
  border-bottom: 1px dashed rgba(254, 251, 241, 0.2);
  outline: none;
  color: #fefbf1;
  font-size: 13px;
  padding: 5px 0;
}

.jv-todo__add input::placeholder {
  color: rgba(254, 251, 241, 0.25);
}

.jv-prompts__intro {
  margin: 0 0 10px;
  font-family: Georgia, 'Times New Roman', serif;
  font-style: italic;
  color: rgba(254, 251, 241, 0.5);
  font-size: 12.5px;
}

.jv-prompts ol {
  margin: 0;
  padding-left: 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.jv-prompts li {
  padding-bottom: 14px;
  border-bottom: 1px dashed rgba(254, 251, 241, 0.12);
}

.jv-notes {
  flex: 1;
  width: 100%;
  box-sizing: border-box;
  resize: none;
  background: none;
  border: 0;
  outline: none;
  color: rgba(254, 251, 241, 0.88);
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 14px;
  line-height: 1.65;
  min-height: 200px;
}

.jv-notes::placeholder {
  color: rgba(254, 251, 241, 0.25);
}

.jv-toc {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
}

.jv-toc__item {
  appearance: none;
  background: rgba(254, 251, 241, 0.04);
  border: 1px solid rgba(254, 251, 241, 0.14);
  border-radius: 999px;
  color: rgba(254, 251, 241, 0.6);
  font-size: 12px;
  padding: 5px 13px;
  cursor: pointer;
  transition: border-color 0.13s ease, color 0.13s ease, box-shadow 0.13s ease;
}

.jv-toc__item:hover {
  border-color: rgba(254, 251, 241, 0.4);
  color: #fefbf1;
}

.jv-toc__item.is-current {
  border-color: rgba(118, 188, 197, 0.8);
  color: #faf4e4;
  box-shadow: 0 0 10px rgba(118, 188, 197, 0.3);
}

.jv-live {
  display: inline-block;
  margin-left: 7px;
  font-style: normal;
  font-size: 8.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(2, 210, 197, 0.9);
  border: 1px solid rgba(2, 210, 197, 0.4);
  border-radius: 999px;
  padding: 1px 6px;
  vertical-align: middle;
}

.jv-editable {
  appearance: none;
  background: none;
  border: 0;
  padding: 0;
  margin: 0;
  font: inherit;
  color: inherit;
  cursor: pointer;
  border-bottom: 1px dashed rgba(118, 188, 197, 0.55);
  transition: border-color 0.13s ease, color 0.13s ease;
}

.jv-editable:hover {
  color: #faf4e4;
  border-bottom-color: rgba(118, 188, 197, 1);
}

.jv-editable__input {
  background: rgba(254, 251, 241, 0.07);
  border: 1px solid rgba(118, 188, 197, 0.7);
  border-radius: 5px;
  outline: none;
  color: #fefbf1;
  font: inherit;
  padding: 1px 6px;
  width: 90px;
  box-sizing: border-box;
}

.jv-widget--progress.is-over .jv-bar__fill {
  background: linear-gradient(90deg, rgba(224, 172, 6, 0.95), rgba(240, 92, 91, 0.9));
}

.jv-x {
  appearance: none;
  background: none;
  border: 0;
  color: rgba(254, 251, 241, 0.25);
  font-size: 15px;
  line-height: 1;
  padding: 2px 5px;
  cursor: pointer;
  border-radius: 4px;
  transition: color 0.12s ease;
}

.jv-x:hover {
  color: rgba(240, 106, 103, 0.95);
}

.jv-tracker__rowctl {
  width: 26px;
  border-bottom: 0 !important;
}

.jv-tracker tbody tr .jv-x {
  opacity: 0;
}

.jv-tracker tbody tr:hover .jv-x {
  opacity: 1;
}

.jv-cell {
  cursor: text;
}

.jv-cell:hover {
  background: rgba(118, 188, 197, 0.07);
}

.jv-tracker td input {
  width: 100%;
  box-sizing: border-box;
  background: rgba(254, 251, 241, 0.06);
  border: 1px solid rgba(118, 188, 197, 0.6);
  border-radius: 4px;
  outline: none;
  color: #fefbf1;
  font-size: 12.5px;
  padding: 3px 5px;
}

.jv-todo__item .jv-x {
  opacity: 0;
  margin-left: auto;
}

.jv-todo__item:hover .jv-x {
  opacity: 1;
}

.jv-todo__text {
  cursor: text;
}

.jv-todo__editinput {
  flex: 1;
  background: rgba(254, 251, 241, 0.06);
  border: 1px solid rgba(118, 188, 197, 0.6);
  border-radius: 4px;
  outline: none;
  color: #fefbf1;
  font-size: 13px;
  padding: 3px 6px;
}

.jv-prompts__q {
  display: block;
  margin-bottom: 7px;
}

.jv-prompts__answer {
  width: 100%;
  box-sizing: border-box;
  resize: vertical;
  min-height: 44px;
  background: rgba(254, 251, 241, 0.04);
  border: 1px solid rgba(254, 251, 241, 0.12);
  border-radius: 7px;
  outline: none;
  color: rgba(254, 251, 241, 0.88);
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 13px;
  line-height: 1.55;
  padding: 8px 10px;
  transition: border-color 0.13s ease;
}

.jv-prompts__answer:focus {
  border-color: rgba(118, 188, 197, 0.7);
}

.jv-prompts__answer::placeholder {
  color: rgba(254, 251, 241, 0.22);
}

.jv-pagepick {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.jv-pagepick__item {
  appearance: none;
  display: flex;
  flex-direction: column;
  gap: 2px;
  text-align: left;
  background: rgba(254, 251, 241, 0.05);
  border: 1px solid rgba(254, 251, 241, 0.14);
  border-radius: 8px;
  padding: 8px 12px;
  cursor: pointer;
  transition: border-color 0.13s ease, box-shadow 0.13s ease;
}

.jv-pagepick__item:hover {
  border-color: rgba(118, 188, 197, 0.85);
  box-shadow: 0 0 10px rgba(118, 188, 197, 0.3);
}

.jv-pagepick__name {
  font-size: 13px;
  color: #fefbf1;
}

.jv-pagepick__from {
  font-size: 9.5px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(118, 188, 197, 0.7);
}

.jv-page__type .jv-x {
  margin-left: 4px;
  font-size: 13px;
}

.rt-host {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
  position: relative;
}

.rt-toolbar {
  position: absolute;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 10;
  display: flex;
  flex-direction: column;
  background: rgba(54, 60, 107, 0.78);
  backdrop-filter: blur(14px);
  border: 1px solid rgba(254, 251, 241, 0.13);
  border-radius: 18px;
  box-shadow: 0 10px 36px rgba(23, 25, 65, 0.55);
  padding: 4px 8px;
  user-select: none;
}

.rt-toolbar--tray {
  position: relative;
  inset: auto;
  left: auto;
  top: auto;
  transform: none;
  z-index: 1;
  width: max-content;
  min-width: max-content;
  max-width: none;
  flex: none;
  border-radius: 16px;
  box-shadow: 0 7px 22px rgba(23, 25, 65, 0.38);
}

.rt-toolbar--tray .rt-row {
  min-width: max-content;
}

.rt-toolbar--tray .rt-btn--tray-dismiss {
  cursor: pointer;
}

.rt-toolbar--tray .rt-btn--tray-dismiss:active {
  cursor: pointer;
}

.rt-toolbar--docked {
  position: relative;
  inset: auto;
  left: auto;
  top: auto;
  transform: none;
  flex: none;
  width: 100%;
  min-width: 0;
  max-width: 100%;
  box-sizing: border-box;
  border-radius: 14px;
  box-shadow: 0 7px 22px rgba(23, 25, 65, 0.38);
}

.rt-toolbar--docked .rt-btn--dock-handle {
  cursor: pointer;
}

.rt-toolbar--docked .rt-btn--dock-handle:active {
  cursor: pointer;
}

.rt-dockscroll {
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  overflow-y: hidden;
  overscroll-behavior-x: contain;
  scrollbar-width: thin;
  scrollbar-color: rgba(254, 251, 241, 0.28) transparent;
}

.rt-dockscroll::-webkit-scrollbar {
  height: 5px;
}

.rt-dockscroll::-webkit-scrollbar-track {
  background: transparent;
}

.rt-dockscroll::-webkit-scrollbar-thumb {
  background: rgba(254, 251, 241, 0.24);
  border-radius: 999px;
}

.rt-dockscroll:focus-visible {
  outline: 2px solid rgba(225, 213, 174, 0.78);
  outline-offset: -2px;
  border-radius: 10px;
}

.rt-dockscroll .rt-row {
  width: max-content;
  min-width: max-content;
}

.rt-row {
  display: flex;
  align-items: center;
  gap: 2px;
}

.rt-row--secondary {
  border-top: 1px solid rgba(254, 251, 241, 0.1);
  margin-top: 4px;
  padding-top: 4px;
}

.rt-sep {
  width: 1px;
  height: 20px;
  background: rgba(254, 251, 241, 0.14);
  margin: 0 5px;
}

.rt-btn {
  appearance: none;
  background: none;
  border: 0;
  border-radius: 9px;
  width: 32px;
  height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: rgba(254, 251, 241, 0.82);
  cursor: pointer;
  transition: background 0.12s ease, color 0.12s ease, box-shadow 0.12s ease;
}

.rt-btn svg {
  width: 17px;
  height: 17px;
}

.rt-btn:hover {
  background: rgba(254, 251, 241, 0.1);
  color: #fefbf1;
}

.rt-btn.is-active {
  background: linear-gradient(180deg, rgba(254, 251, 241, 0.95), rgba(254, 251, 241, 0.62));
  color: #2d3360;
  box-shadow: 0 1px 6px rgba(23, 25, 65, 0.35);
}

.rt-btn.is-active:hover {
  background: linear-gradient(180deg, #fefbf1, rgba(254, 251, 241, 0.75));
  color: #171941;
}

.rt-btn--drag {
  cursor: grab;
  color: rgba(254, 251, 241, 0.45);
}

.rt-btn--drag:active {
  cursor: grabbing;
}

.rt-glyph {
  font-size: 15px;
  line-height: 1;
}

.rt-glyph--h {
  font-size: 13px;
  font-family: var(--ui-font-main), Jost, system-ui, sans-serif;
}

.rt-glyph--h sub {
  font-size: 9px;
}

.rt-chevron {
  display: inline-flex;
  transition: transform 0.18s ease;
}

.rt-chevron.is-open {
  transform: rotate(180deg);
}

.rt-family {
  appearance: none;
  background: rgba(254, 251, 241, 0.07);
  border: 1px solid rgba(254, 251, 241, 0.14);
  border-radius: 8px;
  color: rgba(254, 251, 241, 0.85);
  font-size: 12.5px;
  padding: 4px 8px;
  max-width: 110px;
  outline: none;
  cursor: pointer;
}

.rt-family option {
  background: #2f3564;
}

.rt-size {
  appearance: none;
  width: 44px;
  background: rgba(254, 251, 241, 0.07);
  border: 1px solid rgba(254, 251, 241, 0.14);
  border-radius: 8px;
  color: rgba(254, 251, 241, 0.85);
  font-size: 12.5px;
  padding: 4px 6px;
  margin-left: 4px;
  outline: none;
  box-sizing: border-box;
}

.rt-size::-webkit-inner-spin-button {
  display: none;
}

.rt-family:focus, .rt-size:focus {
  border-color: rgba(118, 188, 197, 0.7);
}

.rt-lineheight {
  max-width: 96px;
}

.rt-linkpanel {
  display: flex;
  flex-direction: column;
  gap: 6px;
  border-top: 1px solid rgba(254, 251, 241, 0.1);
  margin-top: 4px;
  padding: 8px 2px 4px;
  min-width: 340px;
}

.rt-linkrow {
  display: flex;
  align-items: center;
  gap: 10px;
}

.rt-linklabel {
  width: 34px;
  flex: 0 0 auto;
  font-family: var(--ui-font-main), Jost, system-ui, sans-serif;
  font-size: 13px;
  color: rgba(254, 251, 241, 0.45);
}

.rt-linkinput {
  flex: 1;
  appearance: none;
  background: rgba(254, 251, 241, 0.07);
  border: 1px solid rgba(254, 251, 241, 0.12);
  border-radius: 7px;
  color: #fefbf1;
  font-size: 12.5px;
  padding: 6px 9px;
  outline: none;
}

.rt-linkinput:focus {
  border-color: rgba(254, 251, 241, 0.4);
}

.rt-linkinput::placeholder {
  color: rgba(254, 251, 241, 0.28);
  font-style: italic;
}

.rt-prose {
  flex: 1;
  min-height: 200px;
  display: flex;
  flex-direction: column;
}

.rt-prose .ProseMirror {
  flex: 1;
  outline: none;
  color: rgba(254, 251, 241, 0.88);
  font-family: var(--jv-body-font, Georgia, 'Times New Roman', serif);
  font-size: var(--jv-body-size, 14px);
  line-height: var(--jv-lh, 1.65);
  white-space: pre-wrap;
}

.rt-prose .ProseMirror p {
  margin: 0 0 0.6em;
}

.rt-prose .ProseMirror img[data-journal-image] {
  display: block;
  width: auto;
  max-width: 100%;
  max-height: 246px;
  margin: 0.75em auto;
  border: 1px solid rgba(254, 251, 241, 0.2);
  border-radius: 7px;
  object-fit: contain;
  background: rgba(23, 25, 65, 0.16);
  box-shadow: 0 5px 18px rgba(23, 25, 65, 0.25);
}

.jv-attachment-modal {
  width: min(490px, 100%);
}

.jv-attachment-modal__copy {
  margin: -4px 0 18px;
  color: rgba(254, 251, 241, 0.66);
  font-size: 13px;
  line-height: 1.55;
}

.jv-attachment-modal__copy code {
  padding: 1px 4px;
  border-radius: 4px;
  background: rgba(118, 188, 197, 0.15);
  color: rgba(236, 228, 202, 0.96);
}

.rt-prose .ProseMirror h1, .rt-prose .ProseMirror h2, .rt-prose .ProseMirror h3 {
  font-weight: 500;
  color: #fefbf1;
  margin: 0.8em 0 0.35em;
  line-height: 1.25;
}

.rt-prose .ProseMirror h1 {
  font-family: var(--jv-h1-font, var(--ui-font-main), Jost, 'SF Pro', system-ui, sans-serif);
  font-size: 22px;
}

.rt-prose .ProseMirror h2 {
  font-family: var(--jv-h2-font, var(--ui-font-main), Jost, 'SF Pro', system-ui, sans-serif);
  font-size: 18px;
}

.rt-prose .ProseMirror h3 {
  font-family: var(--jv-h3-font, var(--ui-font-main), Jost, 'SF Pro', system-ui, sans-serif);
  font-size: 15.5px;
}

.rt-prose .ProseMirror blockquote {
  margin: 0.6em 0;
  padding: 2px 0 2px 14px;
  border-left: 2px solid rgba(118, 188, 197, 0.55);
  color: rgba(254, 251, 241, 0.62);
  font-style: italic;
}

.rt-prose .ProseMirror ul, .rt-prose .ProseMirror ol {
  margin: 0.4em 0;
  padding-left: 22px;
}

.rt-prose .ProseMirror code {
  background: rgba(254, 251, 241, 0.09);
  border: 1px solid rgba(254, 251, 241, 0.1);
  border-radius: 4px;
  font-family: 'SF Mono', Menlo, monospace;
  font-size: 12px;
  padding: 1px 5px;
}

.rt-prose .ProseMirror a {
  color: rgb(132, 191, 199);
  text-decoration: underline;
  text-decoration-color: rgba(132, 191, 199, 0.45);
}

.rt-prose .ProseMirror p.is-editor-empty:first-child::before {
  content: attr(data-placeholder);
  float: left;
  height: 0;
  pointer-events: none;
  color: rgba(254, 251, 241, 0.25);
  font-style: italic;
}

.jv-typo {
  width: min(440px, 100%);
}

.jv-typo select.jr-input {
  width: 100%;
  cursor: pointer;
}

.jv-typo select.jr-input option, .jv-typo select.jr-input optgroup {
  background: #2f3564;
}

.jv-typo__pair {
  display: flex;
  gap: 12px;
}

.jv-typo__pair .jr-field {
  flex: 1;
}

.jv-typo__hint {
  margin: 2px 0 12px;
  font-size: 12px;
  color: rgba(254, 251, 241, 0.4);
}

.jv-main {
  flex: 1;
  display: flex;
  align-items: stretch;
  gap: 8px;
  min-height: 0;
}

.jv-center {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
  min-height: 0;
}

.jvs {
  width: 210px;
  flex: none;
  display: flex;
  flex-direction: column;
  border: 1px solid rgba(254, 251, 241, 0.1);
  border-radius: 12px;
  background: rgba(23, 25, 65, 0.38);
  overflow: hidden;
  transition: width 0.18s ease, opacity 0.18s ease, border-color 0.18s ease;
}

.jvs.is-closed {
  width: 0;
  opacity: 0;
  border-color: transparent;
  pointer-events: none;
}

.jvs__top {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 12px 10px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.jvs__top::-webkit-scrollbar {
  width: 6px;
}

.jvs__top::-webkit-scrollbar-thumb {
  background: rgba(254, 251, 241, 0.15);
  border-radius: 3px;
}

.jvs__search {
  appearance: none;
  width: 100%;
  box-sizing: border-box;
  background: rgba(254, 251, 241, 0.05);
