.forest-shell {
  --bg-0: #2b3063;
  --bg-1: #272c5d;
  --bg-2: #363c77;
  --glass: rgba(254, 251, 241, 0.08);
  --glass-2: rgba(254, 251, 241, 0.05);
  --glass-3: rgba(254, 251, 241, 0.3);
  --border: rgba(254, 251, 241, 0.12);
  --text: #f1ead5;
  --darktext: #dcad36;
  --muted: rgba(235, 229, 212, 0.66);
  --shadowtop: 0 24px 80px rgba(0, 207, 195, 0.22);
  --shadow: 0 24px 80px rgba(23, 25, 65, 0.45);
  --radius: 24px;
  --card-w: 360px;
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  font-family: var(--ui-font-main), Chillax, Jost, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: var(--text);
  position: relative;
}

.forest-shell * {
  box-sizing: border-box;
}

.forest-shell::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.25;
  background-image: radial-gradient(rgba(254, 251, 241, 0.15) 0.6px, transparent 0.7px);
  background-size: 18px 18px;
  mask-image: linear-gradient(180deg, rgba(23, 25, 65, 0.2), rgba(23, 25, 65, 1));
}

.forest-shell button, .forest-shell input {
  font: inherit;
}

.forest-shell button {
  border: 0;
}

.forest-shell input {
  color: var(--text);
}

.forest-shell [hidden] {
  display: none !important;
}

.aurora {
  position: absolute;
  width: 620px;
  height: 620px;
  border-radius: 50%;
  filter: blur(90px);
  opacity: 0.8;
  pointer-events: none;
  mix-blend-mode: screen;
}

.aurora-a {
  top: -120px;
  left: -80px;
  background: radial-gradient(circle, rgba(0, 207, 195, 0.5), transparent 70%);
  animation: drift-a 18s ease-in-out infinite alternate;
}

.aurora-b {
  top: 8%;
  right: -160px;
  background: radial-gradient(circle, rgba(134, 188, 195, 0.38), transparent 70%);
  animation: drift-b 22s ease-in-out infinite alternate;
}

.aurora-c {
  bottom: -220px;
  left: 22%;
  background: linear-gradient(to bottom left, #414883, #9fb4b7, #dbb24f);
  opacity: 0.35;
  animation: drift-c 20s ease-in-out infinite alternate;
}

.topbar {
  position: absolute;
  top: 0px;
  left: 0px;
  right: 0px;
  z-index: 10;
  display: flex;
  gap: 18px;
  align-items: center;
  padding: 0px 10px;
  padding-top: 3px;
  height: 3rem;
  width: 100%;
  justify-content: space-between;
  border-radius: 0 0 26px 26px;
  background: linear-gradient(115deg, rgba(54, 59, 122, 0.9), rgba(62, 69, 137, 0.72) 45%, rgba(143, 176, 181, 0.38));
  border: 1px solid var(--border);
  backdrop-filter: blur(30px) saturate(260%);
  user-select: none;
  box-shadow: var(--shadowTop);
}

.brand {
  display: flex;
  align-items: center;
  gap: 14px;
  width: min-content;
  -webkit-app-region: drag;
}

.brand-mark {
  position: relative;
  width: 188px;
  height: 58px;
  border-radius: 16px;
  background: conic-gradient(from 120deg, #00c6bb, #0089d7, #7378d1, #aac138, #00c6bb);
  box-shadow: inset 0 1px 0 rgba(232, 211, 140, 0.6), 0 18px 40px rgba(0, 207, 195, 0.25), 0 0 70px #171941;
  -webkit-app-region: drag;
  display: none;
}

.brand-mark::after {
  content: "PJ";
  position: absolute;
  justify-content: center;
  align-items: center;
  display: flex;
  font-size: 2.2rem;
  font-weight: 600;
  inset: 8px;
  border-radius: 12px;
  background: rgba(39, 44, 92, 0.76);
  border: 1px solid rgba(254, 251, 241, 0.08);
  color: #e8d38c;
  -webkit-text-stroke: 1px rgba(0, 207, 195, 0.55);
}

.brand h1 {
  margin: 0;
  font-size: 3.12rem;
  font-family: ZnikomitNo24;
  line-height: 1;
  letter-spacing: 0.01em;
  text-shadow: 3px 2px 1px #171941;
}

.brand h1 span {
  font-family: SF Pro;
  font-size: 2.5rem;
  font-weight: 100;
  color: #00cfc3;
  -webkit-text-stroke: 1px rgba(241, 234, 213, 0.45);
}

.brand p {
  margin: 6px 0 0;
  font-size: 0.9rem;
}

.toolbar {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-direction: row;
  overflow: scroll;
  height: 100%;
}

.toolbar::-webkit-scrollbar {
  display: none;
}

.search-wrap {
  position: absolute;
  flex: 1;
  top: 3rem;
  left: 34px;
  min-width: 220px;
}

.collapse-all-btn {
  position: absolute;
  top: 3rem;
  right: 14px;
  z-index: 2;
  display: grid;
  width: 60px;
  height: 29px;
  padding: 0;
  align-items: center;
  justify-content: center;
  color: #f2e6c0;
  background: rgba(55, 61, 123, 0.9);
  border: 1px solid rgba(248, 224, 159, 0.25) !important;
  border-top: 0 !important;
  border-radius: 0 0 11px 11px;
  box-shadow: inset 0 -1px 0 rgba(254, 251, 241, 0.08), 0 5px 16px rgba(23, 25, 65, 0.22);
  cursor: pointer;
  transition: color 0.16s ease, background 0.16s ease, transform 0.16s ease, opacity 0.16s ease;
}

.collapse-all-btn span {
  font-family: SF Pro;
}

.collapse-all-btn:hover:not(:disabled) {
  color: #fdf5df;
  background: rgba(49, 99, 113, 0.96);
  transform: translateY(2px);
}

.collapse-all-btn:focus-visible {
  outline: 2px solid rgba(242, 230, 192, 0.9);
  outline-offset: 2px;
}

.collapse-all-btn:disabled {
  opacity: 0.38;
  cursor: default;
}

.dim-mode .search-wrap {
  top: 1.5rem;
  transform: scale(.9);
}

.dim-mode .collapse-all-btn {
  top: 1.5rem;
}

.search-wrap::before {
  content: "⌕";
  position: absolute;
  left: 8px;
  top: 50%;
  transform: translateY(-50%);
  color: rgba(239, 227, 189, 0.307);
  font-size: 3rem;
  pointer-events: none;
}

.search-wrap input {
  width: 5%;
  padding: 2px 2px;
  padding-left: 40px;
  border-radius: 0 0 10px 10px;
  border: 1px solid rgba(254, 251, 241, 0.1);
  border-top: none;
  background: rgba(75, 83, 167, 0.6);
  outline: none;
  color: #fefbf1 !important;
  box-shadow: inset 0 1px 0 rgba(23, 25, 65, 1);
  transition: all .3s;
}

.search-wrap input:focus {
  width: 100%;
  padding: 9px 50px;
  box-shadow: inset 0 -2px 7px rgba(23, 25, 65, 1);
}

.search-wrap input::placeholder {
  color: #a9c200;
}

.ghost-btn {
  padding: 4px 6px;
  border-radius: 14px;
  color: var(--text);
  border: 1px solid rgba(254, 251, 241, 0.4) !important;
  background: rgba(32, 35, 87, 0.5);
}

.ghost-btn:hover {
  transform: translateY(-1px);
  background: rgba(254, 251, 241, 0.09);
  border-color: rgba(254, 251, 241, 0.16);
}

.status-pills {
  display: none;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  justify-content: center;
  justify-items: center;
  align-items: center;
  text-align: center;
  gap: 4px;
  min-width: 30%;
  max-width: 30%;
  overflow: hidden;
  width: 30%;
}

.stat-pill {
  width: fit-content;
  height: 1rem;
  border-radius: 999px;
  display: flex;
  font-size: 1rem;
  color: #fefbf1;
  padding: 0 4px;
  text-align: center;
  justify-content: center;
  background: rgba(23, 25, 65, 0.1);
  border: 1px solid rgba(254, 251, 241, 0.09);
  max-width: 3.5rem;
  min-width: 3.5rem;
  overflow: hidden;
}

.stat-pill.subtle {
  color: var(--muted);
}

.hud.help-bubble {
  position: absolute;
  top: 110px;
  left: 28px;
  z-index: 7;
  padding: 10px 14px;
  border-radius: 14px;
  font-size: 0.84rem;
  color: var(--muted);
  background: rgba(43, 47, 97, 0.55);
  border: 1px solid rgba(254, 251, 241, 0.08);
  backdrop-filter: blur(14px);
}

.stage {
  position: absolute;
  inset: 0px;
  overflow: hidden;
  border-radius: 30px;
  border: 1px solid rgba(254, 251, 241, 0.12);
  background: radial-gradient(circle at 50% 16%, rgba(181, 207, 40, 0.08), transparent 38%), radial-gradient(ellipse 640px 420px at 76% 68%, rgba(219, 178, 80, 0.08), transparent 70%), radial-gradient(ellipse 520px 380px at 28% 40%, rgba(158, 176, 179, 0.09), transparent 70%), radial-gradient(circle at 16% 86%, rgba(76, 164, 224, 0.14), transparent 36%), linear-gradient(160deg, #2d3265, #3b417d 50%, #32376e);
  box-shadow: inset 0 1px 0 rgba(254, 251, 241, 0.06), var(--shadow);
  touch-action: none;
  filter: brightness(1);
  cursor: grab;
}

.stage::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(circle at center, transparent 35%, rgba(23, 25, 65, 0.14) 100%), linear-gradient(180deg, transparent, rgba(23, 25, 65, 0.1));
}

.grid {
  position: absolute;
  inset: 0;
  pointer-events: none;
  --minor: 48px;
  --major: 240px;
  --off-x: 0px;
  --off-y: 0px;
  --major-off-x: 0px;
  --major-off-y: 0px;
  background-image: linear-gradient(rgba(80, 168, 229, 0.05) 1px, transparent 1px), linear-gradient(90deg, rgba(77, 80, 205, 0.09) 1.5px, transparent 1px), linear-gradient(rgba(220, 209, 175, 0.09) 1px, transparent 3px), linear-gradient(90deg, rgba(220, 209, 175, 0.09) 1px, transparent 1px);
  background-size: var(--minor) var(--minor), var(--minor) var(--minor), var(--major) var(--major), var(--major) var(--major);
  background-position: var(--off-x) var(--off-y), var(--off-x) var(--off-y), var(--major-off-x) var(--major-off-y), var(--major-off-x) var(--major-off-y);
  opacity: 0.9;
}

.world {
  position: absolute;
  inset: 0;
  transform-origin: 0 0;
  will-change: transform;
}

.forest-shell.is-panning, .forest-shell.is-panning .stage, .forest-shell:has(.project-card.forest-dragging) {
  cursor: grabbing;
}

.project-card {
  cursor: grab;
  position: absolute;
  max-height: 400px;
  width: var(--card-w);
  border-radius: var(--ui-forest-card-radius, 10px 80px 2px 130px);
  corner-shape: var(--ui-corner-shape);
  overflow: hidden;
  border: 1.2px solid rgba(188, 216, 0, 1);
  background: linear-gradient(180deg, rgba(54, 60, 117, 0.86), rgba(44, 49, 98, 0.78));
  box-shadow: 0 22px 60px rgba(23, 25, 65, 0.36);
  user-select: none;
  transition: all .4s ease;
  min-height: 80px;
  padding-left: 3px;
  padding-right: 20px;
}

.project-header[data-drag-handle] {
  cursor: grab;
}

[data-role="cover-drag-area"] {
  cursor: grab;
}

.project-card.forest-dragging, .project-card.forest-dragging [data-drag-handle] {
  cursor: grabbing;
}

.viewer-timeline-action-btn.tl-add-toggle.forest-active {
