  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: rgba(254, 251, 241, 0.06);
  color: var(--muted);
  font-size: 13px;
  cursor: pointer;
}

.tl-modal-close:hover {
  background: rgba(254, 251, 241, 0.12);
  color: #fefbf1;
}

