  border: 1px solid rgba(254, 251, 241, 0.12);
  backdrop-filter: blur(18px);
  box-shadow: 0 16px 50px rgba(23, 25, 65, 0.28), inset 0 0 60px #171941;
  background: linear-gradient(to bottom, #ead282, #00687f 30%, #b73e04, #006378, rgb(54, 59, 123));
}

.tag-strip {
  position: absolute;
  left: -10px;
  right: -10px;
  bottom: -1px;
  z-index: 8;
  display: flex;
  gap: 10px;
  align-items: center;
  height: 104px;
  padding: 56px 14px 0;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
  pointer-events: none;
}

.tag-strip>* {
  pointer-events: auto;
}

.dim-mode .tag-strip-ground {
  background: linear-gradient(to bottom, #ead282, #417585 30%, #322c9d, #454c86);
}

.tag-strip::-webkit-scrollbar {
  display: none;
}

.tag-strip-empty {
  color: var(--muted);
  font-size: 0.84rem;
}

.global-tag {
  transition: all .15s cubic-bezier(.3, .75, .7, 1.2);
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex-wrap: nowrap;
  text-wrap: nowrap;
  width: 80px;
  overflow: hidden;
  padding: 2px 5px;
  border-radius: 999px;
  color: rgba(254, 251, 241, 0.94);
  background: rgba(254, 251, 241, 0.1);
  border: .5px solid rgba(254, 251, 241, 0.7) !important;
}

.global-tag span {
  font-size: 0.78rem;
  color: rgba(254, 251, 241, 0.72);
}

.global-tag:hover {
  width: 120px;
  transform: translateY(-1px);
  background: rgba(254, 251, 241, 0.1);
  border-color: rgba(254, 251, 241, 0.16);
}

.global-tag-slot {
  position: relative;
  display: inline-flex;
  flex: none;
}

.global-tag-slot .global-tag {
  position: relative;
  z-index: 1;
  cursor: pointer;
}

.global-tag-slot.is-bloomed .global-tag {
  transform: translateY(calc(-1 * var(--bloom-lift, 56px)));
  width: auto;
  min-width: 80px;
  max-width: 170px;
  color: #3e4583;
  background: linear-gradient(180deg, #fef5dd, #ede4c8);
  border-color: rgba(251, 226, 158, 0.95) !important;
  box-shadow: 0 6px 18px rgba(23, 25, 65, 0.35), 0 0 16px rgba(248, 223, 154, 0.5);
}

.global-tag-slot.is-bloomed .global-tag span {
  color: rgba(62, 69, 131, 0.65);
}

.global-tag-slot.is-bloomed .global-tag:hover {
  transform: translateY(calc(-3px - var(--bloom-lift, 56px)));
  background: linear-gradient(180deg, #fef7e3, #f0e8d1);
  border-color: #fbe29e !important;
}

.tag-bloom-sprite {
  position: absolute;
  left: 50%;
  bottom: -6px;
  width: 28px;
  height: calc(var(--bloom-lift, 56px) + 16px);
  transform: translateX(-50%);
  transform-origin: bottom center;
  z-index: 0;
  cursor: pointer;
}

.tag-bloom-sprite .bloom-stem {
  stroke: #849800;
  stroke-width: 2.6;
  stroke-linecap: round;
}

.tag-bloom-sprite .bloom-leaf {
  fill: #8a9f00;
  transform-box: fill-box;
  animation: bloom-leaf-flutter var(--bloom-flutter, 3.4s) ease-in-out infinite alternate;
}

.tag-bloom-sprite .bloom-leaf.left {
  transform-origin: right center;
}

.tag-bloom-sprite .bloom-leaf.right {
  fill: #31839d;
  transform-origin: left center;
  animation-duration: calc(var(--bloom-flutter, 3.4s) * 0.82);
  animation-delay: 0.4s;
}

.tag-bloom-sprite .bloom-petals ellipse {
  fill: #dbc888;
}

.tag-bloom-sprite .bloom-petals .crown {
  fill: #dfcf9a;
}

.global-tag-slot.is-sprouting .global-tag {
  animation: bloom-sprout-chip var(--bloom-dur, 0.5s) ease-out var(--bloom-delay, 0s) backwards;
}

.global-tag-slot.is-sprouting .tag-bloom-sprite {
  animation: bloom-sprout-stem var(--bloom-dur, 0.5s) ease-out var(--bloom-delay, 0s) backwards;
}

.global-tag-slot.is-wilting .global-tag {
  animation: bloom-wilt-chip 0.32s ease-in forwards;
}

.global-tag-slot.is-wilting .tag-bloom-sprite {
  animation: bloom-wilt-stem 0.32s ease-in forwards;
}

