  font-size: 0.72rem;
  font-weight: 700;
  color: rgba(254, 251, 241, 0.7);
  letter-spacing: 0.02em;
}

.tl-axis-days {
  top: 48px !important;
  font-size: 0.68rem;
  font-weight: 600;
  color: rgba(254, 251, 241, 0.55);
}

.tl-axis-hours {
