.tl-axis-label {
  position: absolute;
  transform: translateX(-50%);
  white-space: nowrap;
  text-shadow: 0 1px 2px rgba(23, 25, 65, 0.9), 0 0 8px rgba(23, 25, 65, 0.5);
  pointer-events: none;
}

.tl-ghost {
  position: absolute;
  top: 0;
  transform: translateX(-50%);
  pointer-events: none;
  z-index: 5;
}

.tl-ghost::before {
  content: '';
  position: absolute;
  left: 50%;
  top: 20px;
  transform: translateX(-50%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(var(--accent-rgb), 0.3);
  border: 2px dashed rgba(var(--accent-rgb), 0.6);
  box-shadow: 0 0 20px rgba(var(--accent-rgb), 0.2);
  animation: ghostPulse 1.5s ease-in-out infinite;
}

.tl-ghost-label {
  position: absolute;
  bottom: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
  padding: 4px 10px;
  background: rgba(47, 52, 105, 0.95);
  border: 1px solid rgba(var(--accent-rgb), 0.3);
  border-radius: 8px;
  font-size: 0.72rem;
  font-weight: 600;
  color: rgba(var(--accent-rgb), 0.9);
  white-space: nowrap;
  box-shadow: 0 4px 12px rgba(23, 25, 65, 0.3);
}

.tl-ghost-label::after {
  content: '';
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  border: 5px solid transparent;
  border-top-color: rgba(var(--accent-rgb), 0.3);
}

.tl-pending-indicator {
  position: absolute;
  bottom: -30px;
  left: 50%;
  transform: translateX(-50%);
